INSERT INTO public.canonical_categories VALUES (8, 'Financial Aid', 'Title IV, student loans, FAFSA', NULL, NULL, 8, true, '2026-03-15 17:44:51.094004');
INSERT INTO public.canonical_categories VALUES (10, 'Contracts & Procurement', 'Purchasing, vendor management, RFPs', NULL, NULL, 10, true, '2026-03-15 17:44:51.094004');
INSERT INTO public.canonical_categories VALUES (11, 'Intellectual Property', 'Copyright, patents, tech transfer', NULL, NULL, 11, true, '2026-03-15 17:44:51.094004');
INSERT INTO public.canonical_categories VALUES (12, 'Ethics & Governance', 'Board governance, conflict of interest, lobbying', NULL, NULL, 12, true, '2026-03-15 17:44:51.094004');
INSERT INTO public.canonical_categories VALUES (13, 'Fundraising & Development', 'Donor relations, charitable giving', NULL, NULL, 13, true, '2026-03-15 17:44:51.094004');
INSERT INTO public.canonical_categories VALUES (14, 'Athletics', 'NCAA, intercollegiate sports compliance', NULL, NULL, 14, true, '2026-03-15 17:44:51.094004');
INSERT INTO public.canonical_categories VALUES (15, 'Student Services', 'Student affairs, housing, international students', NULL, NULL, 15, true, '2026-03-15 17:44:51.094004');
INSERT INTO public.canonical_categories VALUES (3, 'Finance', 'Financial reporting, tax, treasury', NULL, NULL, 3, true, '2026-03-15 17:44:51.094004');
