INSERT INTO public.users VALUES (43, 'brandesd@moravian.edu', '', 'admin', NULL, 'brandesd@moravian.edu', 'David', 'Brandes', 'brandesd@moravian.edu', NULL, 'saml', '2026-08-17 23:48:19.484', '2026-06-25 15:42:24.465506', '2026-06-25 15:42:24.465506', '["admin"]', NULL, false, NULL, NULL, '2026-08-17 23:58:22.58', 'valid', false);
INSERT INTO public.regulations VALUES (1, 'age-discrimination-act-of-1975', 'Age Discrimination Act of 1975', 'Diversity/Affirmative Action', '42 U.S.C. §§ 6101-6107', NULL, 'Prohibits discrimination based on age in educational or academic programs or activities that receive federal financial assistance.
INSERT INTO public.regulations VALUES (2, 'higher-education-act-institutional-and-financial-a', 'Higher Education Act: Institutional and financial assistance information for students', 'Copyright & Trademark', '20 U.S.C. § 1092(a)(1)(P); Public Law  No. 110-315 §§ 152 -153', NULL, 'Requires the following disclosures to enrolled students: (a) Policies/sanctions for copyright infringement; and (b) annual disclosure detailing federal copyright penalties.', '', 'Intellectual Property', 'federal', true, NULL, NULL, '2026-06-25 15:35:08.270423', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Higher Education Act''s Institutional and Financial Assistance Information for Students provisions, codified at 20 U.S.C. § 1092, establish comprehensive annual disclosure requirements for institutions participating in federal student aid programs under Title IV. These consumer information disclosures ensure prospective and enrolled students have access to essential institutional data for informed decision-making.
INSERT INTO public.regulations VALUES (3, 'higher-education-act-textbook-information', 'Higher Education Act: Textbook Information', 'Academic Programs', '20 USC § 1015(b)', NULL, 'Requires disclosure of the course schedule along with the International Standard Book Number (ISBN) of every required and recommended textbook and supplemental material and retail price information to all prospective and enrolled students.', '', 'Academic Programs', 'federal', true, NULL, NULL, '2026-06-25 15:35:08.299236', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Higher Education Act''s Textbook Information provision, codified at 20 U.S.C. § 1015(b), mandates comprehensive disclosure requirements for course materials at institutions of higher education participating in federal student aid programs. This regulation, implemented through 34 C.F.R. § 668.41, requires institutions to provide detailed textbook and supplemental material information to enable students to make informed financial decisions regarding educational expenses.
INSERT INTO public.regulations VALUES (4, 'higher-education-opportunity-act-sections-152-and-', 'Higher Education Opportunity Act Sections 152 and 153', 'Academic Programs', 'Public Law No. 110-315', NULL, '<li style="list-style-type: none">
INSERT INTO public.regulations VALUES (5, 'section-504-of-the-rehabilitation-act-of-1973', 'Section 504 of The Rehabilitation Act of 1973', 'General', '29 U.S.C. § 701', NULL, 'Your organization must prevent discrimination against individuals with disabilities in all programs and activities receiving federal financial assistance. You must ensure equal access, provide reasonable accommodations, and implement nondiscrimination policies similar to those required under Title VI and Title IX.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (6, 'teacher-preparation-programs', 'Teacher Preparation Programs', 'General', '20 U.S.C. §§ 1022 - 1022h', NULL, 'Your institution must submit comprehensive annual report cards if you offer teacher preparation programs leading to initial certification. You must provide detailed performance data including licensing exam pass rates, clinical experience hours, program goals, and improvement strategies to maintain federal funding eligibility.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (7, 'bankruptcy-abuse-prevention-consumer-protection-ac', 'Bankruptcy Abuse Prevention & Consumer Protection Act of 2005', 'Accounting', '11 U.S.C. §§ 101-1532; Public Law No. 109-8', NULL, 'Prohibits the discharge of most student loans in bankruptcy, when the loans were obtained from the government or non-profit higher educational institutions.
INSERT INTO public.regulations VALUES (8, 'clayton-antitrust-act-of-1914', 'Clayton Antitrust Act of 1914', 'Accounting', '15 U.S.C. §§ 12-27', NULL, 'Enacted as a supplement to the Sherman Act.
INSERT INTO public.regulations VALUES (9, 'fair-credit-reporting-act-fcra', 'Fair Credit Reporting Act (FCRA)', 'Recruitment Hiring & Termination', '15 U.S.C. §§ 1681-1681x', NULL, 'Employers, before obtaining a consumer report (including criminal background checks) must disclose in writing to the applicant or employee that it may obtain a consumer report for employment purposes, and secondly, secure the written consent of the applicant or employee.
INSERT INTO public.regulations VALUES (10, 'federal-insurance-contributions-act-fica', 'Federal Insurance Contributions Act (FICA)', 'Wages', '42 U.S.C. §§ 401-434', NULL, 'Provides that service performed in the employ of a school, college or university by a student who is enrolled and regularly attending classes at such school, college, or university is exempt from the FICA tax.
INSERT INTO public.regulations VALUES (11, 'federal-unemployment-tax-act-futa', 'Federal Unemployment Tax Act (FUTA)', 'Accounting', '26 U.S.C. §§ 3301-3311', NULL, '<li style="list-style-type: none">
INSERT INTO public.regulations VALUES (12, 'higher-education-act-disclosure-of-foreign-gifts', 'Higher Education Act – Disclosure of Foreign Gifts', 'Accounting', '20 U.S.C. § 1011f', NULL, 'The University is required to submit a disclosure report for gifts and contracts of $250,000 or more with a foreign source to the Department of Education. This page serves as a repository for all relevant data, information, guidance, and training related to the required foreign gift and contract reporting.', '', 'Finance', 'federal', true, NULL, NULL, '2026-06-25 15:35:08.726971', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Higher Education Act''s Foreign Gift and Contract Disclosure provisions, codified at 20 U.S.C. § 1011f and implemented through 34 CFR § 668.14(b)(20), mandate comprehensive reporting requirements for institutions of higher education receiving foreign financial contributions. This federal regulation requires institutions to disclose gifts and contracts from foreign sources valued at $250,000 or more, either individually or cumulatively from the same source within a calendar year.
INSERT INTO public.regulations VALUES (13, 'qualified-tuition-and-student-loan-interest-report', 'Qualified Tuition and Student Loan Interest Reporting', 'Tax', '26 U.S.C. Sec. 6050S', NULL, 'Institutions must report (1) qualified tuition and related expenses and (2) student loan interest to the IRS.
INSERT INTO public.regulations VALUES (14, 'regulation-e-electronic-fund-transfers', 'Regulation E: Electronic Fund Transfers', 'Accounting', '15 U.S.C. § 1693b', NULL, 'Establishes the basic rights, liabilities and responsibilities of consumers who use electronic fund transfer services and of financial institutions that offer these services.', '', 'Finance', 'federal', true, NULL, NULL, '2026-06-25 15:35:08.983293', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'Regulation E, codified under 15 U.S.C. § 1693 et seq. and implemented through 12 CFR Part 1005, establishes comprehensive consumer protection standards for electronic fund transfers (EFTs) that significantly impact higher education institutions managing student financial services. The regulation, enforced by the Consumer Financial Protection Bureau (CFPB) under authority granted by the Electronic Fund Transfer Act, applies to all institutions offering electronic payment services, including universities providing student debit cards, online payment systems, and electronic disbursement of financial aid.
INSERT INTO public.regulations VALUES (15, 'sarbanes-oxley-act-of-2002-sox', 'Sarbanes Oxley Act of 2002 (SOX)', 'Accounting', 'Public Law No. 107-204', NULL, 'Designed to protect investors by improving the accuracy and reliability of corporate disclosures made pursuant to the securities laws.
INSERT INTO public.regulations VALUES (16, 'sherman-antitrust-act', 'Sherman Antitrust Act', 'Accounting', '15 U.S.C. §§ 1-7', NULL, 'Prohibits “every contract, combination…, or conspiracy, in restraining of trade or commerce among the several States, or with foreign nations.”
INSERT INTO public.regulations VALUES (17, 'social-security-act', 'Social Security Act', 'Accounting', '42 U.S.C. §§ 301-1397mm', NULL, 'An employer must pay social security taxes on employees but an exemption exists for most students also working for the University, for clergy whose services are performed in the exercise of their ministry, and for professional employees as defined in 26 CFR § 31.3121(b)(10)-2.
INSERT INTO public.regulations VALUES (18, 'tax-cuts-and-jobs-act-of-2017-endowment-excise-tax', 'Tax Cuts and Jobs Act of 2017 (endowment excise tax)', 'Accounting', '26 U.S.C. § 4968', NULL, 'Imposes a 1.4 percent excise tax on the net investment income of private institutions that:
INSERT INTO public.regulations VALUES (19, 'truth-in-lending-act', 'Truth in Lending Act', 'Accounting', '15 U.S.C. §§ 1601-1693r', NULL, 'Requires disclosure statements for loans and credit plans, but exempts Perkins Loans and Federal Family Education Loans.
INSERT INTO public.regulations VALUES (20, 'uniform-administrative-requirements-cost-principle', 'Uniform Administrative Requirements, Cost Principles, and Audit Requirements for Federal Awards (Uniform Guidance, Super Circular, or Omni Circular)', 'Accounting', 'Uniform Administrative Requirements, Cost Principles, and Audit Requirements for Federal Awards (Uniform Guidance, Super Circular, or Omni Circular)', NULL, 'The Uniform Guidance streamlines and consolidates the federal government’s guidance on administrative rules, cost principles, and audit requirements for federal awards (including sponsored research awards and others awarded to institutions) across the entire federal government. Also requires disclosures of potential conflicts of interest or criminal violations.
INSERT INTO public.regulations VALUES (21, 'unrelated-business-income-tax-ubit', 'Unrelated Business Income Tax (UBIT)', 'Accounting', '26 U.S.C. § 511', NULL, 'Regulates unrelated business income, which is income from a trade or business, regularly carried on, that is not substantially related to the charitable, educational, or other purpose that is the basis of the organization''s exemption.', '', 'Finance', 'federal', true, NULL, NULL, '2026-06-25 15:35:09.208393', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Unrelated Business Income Tax (UBIT) regulation under 26 U.S.C. § 511 imposes federal income tax on tax-exempt organizations, including higher education institutions, for income derived from unrelated business activities. This regulation ensures that exempt organizations do not gain unfair competitive advantages over taxable businesses while engaging in commercial activities unrelated to their exempt purposes.
INSERT INTO public.regulations VALUES (22, 'higher-education-act-recognition-of-accrediting-ag', 'PA Act 36 of 1990 - English Fluency in Higher Ed', 'General', '24 P.S. § 6803 et seq.', NULL, 'Your higher education institution must ensure your accrediting agency enforces standards that respect your institutional mission while maintaining educational program quality across all delivery methods. You must demonstrate measurable outcomes that achieve your stated educational objectives and maintain adequate resources to support program delivery whether through traditional classroom, distance education, or correspondence programs.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (23, 'higher-education-act-readmission-requirements-for-', 'Higher Education Act: Readmission Requirements for Servicemembers', 'Admissions', '20 U.S.C. § 1091c', NULL, 'Requires that the University readmit students who left in order to join the military. The student must be readmitted in the same academic status. Generally, the length of absence cannot be greater than five (5) years. Exceptions to this law include those veterans receiving a dishonorable discharge or bad conduct charge, those who were court marshaled, and those who the University is reasonably unable to prepare to resume or complete their program.', '', 'Academic Programs', 'federal', true, NULL, NULL, '2026-06-25 15:35:09.266473', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Higher Education Act Readmission Requirements for Servicemembers, codified at 20 U.S.C. § 1091c, establishes comprehensive protections for students who interrupt their higher education to serve in the uniformed services. This federal mandate requires institutions of higher education participating in Title IV federal student aid programs to readmit qualified servicemembers to their original academic programs with the same academic status they held prior to military service.
INSERT INTO public.regulations VALUES (24, 'equity-in-athletics-disclosure-act-eada', 'Equity in Athletics Disclosure Act (EADA)', 'General', '20 U.S.C. § 1092(g)', NULL, 'Your organization must provide equal access and reasonable accommodations for individuals with disabilities in all state and local government services. You must ensure physical accessibility, provide auxiliary aids and services, modify policies when necessary, and maintain effective communication with disabled individuals.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (25, 'title-ix-of-the-education-amendments-of-1972', 'Title IX of the Education Amendments of 1972', 'General', '20 U.S.C. § 1681', NULL, 'Your institution must prohibit retaliation against individuals who exercise their Title IX rights or participate in Title IX proceedings. You must prevent intimidation, threats, coercion, or discrimination against those who file complaints, serve as witnesses, or participate in investigations and hearings under Title IX.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (26, 'americans-with-disabilities-act', 'Americans with Disabilities Act (ADA)', 'General', '42 U.S.C. §§ 12101-12213', NULL, 'Your organization must provide equal access and reasonable accommodations for individuals with disabilities in all state and local government services. You must ensure physical accessibility, provide auxiliary aids and services, modify policies when necessary, and maintain effective communication with disabled individuals.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (27, 'campus-sex-crimes-prevention-act-1601-of-the-victi', 'Campus Sex Crimes Prevention Act (§ 1601 of the Victims of Trafficking and Violence Protection Act of 2000)', 'Sexual Misconduct', 'Public Law No. 106-386 (Title VI)', NULL, 'The Campus Sex Crimes Prevention Act requires sex offenders, who must register under state law, to provide notice of enrollment or employment at any institution of higher education (IHE) in that state where the offender resides, as well as notice of each change of enrollment or employment status at the IHE. In turn, this information will be made available by the state authorities to the local law enforcement agency that has jurisdiction where the IHE is located.', 'CAMPUS SEX CRIMES PREVENTION ACT (CSCPA) REQUIREMENTS:
INSERT INTO public.regulations VALUES (28, 'drug-free-schools-and-communities-act', 'Drug-Free Schools and Communities Act', 'Campus Safety', '20 U.S.C. § 1011i', NULL, 'Requires distribution of the college or university''s drug and alcohol prevention and policy information every year and biennial review of drug and alcohol prevention program.', '', 'Campus Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:09.606964', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Drug-Free Schools and Communities Act, codified at 20 U.S.C. § 1011i, establishes comprehensive requirements for institutions of higher education to maintain drug and alcohol abuse prevention programs as a condition of receiving federal financial assistance. This federal mandate, originally enacted as part of the Drug-Free Schools and Communities Act of 1989 and subsequently amended, requires colleges and universities to implement, maintain, and regularly evaluate programs designed to prevent the unlawful possession, use, or distribution of illicit drugs and alcohol by students and employees on institutional property or as part of institutional activities.
INSERT INTO public.regulations VALUES (29, 'emergency-planning-and-community-right-to-know-act', 'Emergency Planning and Community Right to Know Act (EPCRA)', 'General', '42 U.S.C. §§ 11001 - 11050', NULL, 'Your institution must comply with emergency planning and hazardous substance reporting requirements if you store chemicals above threshold quantities. You must notify emergency planning committees, submit annual chemical inventory reports, and coordinate with local emergency responders for campus safety planning.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (30, 'higher-education-act-drug-and-alcohol-abuse-preven', 'Higher Education Act: Drug and Alcohol Abuse Prevention', 'General', '20 U.S.C. § 1011i', NULL, 'Your institution must maintain comprehensive drug and alcohol abuse prevention programs and conduct biennial effectiveness reviews to remain eligible for federal funding. You must annually distribute written materials to all students and employees detailing conduct standards, legal sanctions, health risks, available resources, and disciplinary consequences.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (31, 'higher-education-act-program-participation-agreeme', 'Higher Education Act: Program Participation Agreements', 'General', '20 U.S.C. § 1094', NULL, 'Your institution must disclose disciplinary proceeding outcomes to victims of violent crimes and non-forcible sex offenses upon request under your Program Participation Agreement with the Department of Education. You must provide simultaneous written notification to both accusers and accused parties regarding outcomes of proceedings involving domestic violence, dating violence, sexual assault, or stalking allegations.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (48, 'lanham-act', 'Lanham Act', 'Copyright & Trademark', '15 U.S.C. §§ 1051-1141n', NULL, 'Prohibits trademark infringement, trademark dilution, and false advertising.', '', 'Intellectual Property', 'federal', true, NULL, NULL, '2026-06-25 15:35:10.624313', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Lanham Act, codified at 15 U.S.C. §§ 1051-1141n, establishes the federal trademark registration system and provides comprehensive protection against trademark infringement, trademark dilution, and false advertising. Originally enacted in 1946 and substantially amended by the Trademark Law Revision Act of 1988, the Act serves as the primary federal framework governing trademark rights and commercial speech.
INSERT INTO public.regulations VALUES (32, 'jeanne-clery-disclosure-of-campus-security-policy-', 'Jeanne Clery Disclosure of Campus Security Policy and Campus Crime Statistics Act', 'General', '20 U.S.C. § 1092', NULL, 'Your institution must annually disclose campus security policies and crime statistics to current and prospective students and employees. You must publish an Annual Security Report containing three years of campus crime data, security policies, and emergency procedures, while maintaining a daily crime log available for public inspection.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (33, 'occupational-safety-and-health-act-of-1970', 'OSHA', 'Campus Safety', '29 U.S.C. §§ 651-678', NULL, 'Each institution must have a written emergency action plan kept in the workplace and available for employee review upon request, as required under OSHA standards.', '', 'Campus Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:09.772085', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Occupational Safety and Health Act of 1970 (OSH Act), codified at 29 U.S.C. §§ 651-678, establishes comprehensive workplace safety standards that apply to higher education institutions as employers. The Act empowers the Occupational Safety and Health Administration (OSHA) to enforce safety standards and requires employers to maintain safe working environments for all employees, including faculty, staff, and student workers.
INSERT INTO public.regulations VALUES (34, 'title-vi-of-the-civil-rights-act-of-1964-42-u-s-c-', 'Title VI of the Civil Rights Act of 1964  42 U.S.C. §§ 2000d-2000d-7', 'Campus Safety', '42 U.S.C. § 2000d et seq.; 34 CFR Part 100', NULL, 'Prohibits discrimination based on race, color, or national origin in educational and/or academic programs or activities receiving federal financial assistance.
INSERT INTO public.regulations VALUES (35, 'anti-kickback-act-of-1986', 'Anti-Kickback Act of 1986', 'Contracts & Procurement', '41 U.S.C. §§ 8701-8707', NULL, 'Prohibits any payment or gratuity made for the purpose of inducing award of a subcontract or prime contract with the federal government.', '', 'Contracts & Procurement', 'federal', true, NULL, NULL, '2026-06-25 15:35:10.062223', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Anti-Kickback Act of 1986, codified at 41 U.S.C. §§ 8701-8707, establishes a comprehensive federal prohibition against kickbacks in government contracting, directly impacting higher education institutions that receive federal contracts. The Act criminalizes any payment, gift, or gratuity provided to induce the award of a federal contract or subcontract, protecting the integrity of the federal procurement process.
INSERT INTO public.regulations VALUES (36, 'anti-discrimination-laws-for-federal-contractors', 'Anti-discrimination laws for federal contractors', 'Contracts & Procurement', 'Executive Order 11246; 41 CFR Part 60', NULL, 'For information about anti-discrimination laws applicable to federal contractors, including colleges and universities, see Human Resources: Discrimination section of the Compliance Matrix.', '', 'Contracts & Procurement', 'federal', true, NULL, NULL, '2026-06-25 15:35:10.090764', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'Anti-discrimination laws for federal contractors establish comprehensive civil rights protections applicable to higher education institutions receiving federal contracts or financial assistance. The primary legal framework derives from Executive Order 11246 (41 U.S.C. § 4212), Section 503 of the Rehabilitation Act of 1973 (29 U.S.C. § 793), and the Vietnam Era Veterans'' Readjustment Assistance Act (38 U.S.C. § 4212), implemented through 41 CFR Parts 60-1 through 60-741.
INSERT INTO public.regulations VALUES (46, 'copyright-term-extension-act', 'Copyright Term Extension Act', 'Copyright & Trademark', 'Public Law No. 10-298', NULL, 'Extends by 20 years the length of protection afforded to copyrighted works, and thus lengthens the amount of time it will take for a work to enter the public domain.
INSERT INTO public.regulations VALUES (37, 'byrd-amendment', 'Byrd Amendment', 'Tax', '31 U.S.C. § 1352', NULL, 'Requires disclosure of lobbying activities when receiving federal contracts, grants, loans or cooperative agreements.', '', 'Finance', 'federal', true, NULL, NULL, '2026-06-25 15:35:10.141961', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Byrd Amendment, codified at 31 U.S.C. § 1352 and implemented through 28 CFR Part 69, establishes comprehensive restrictions on the use of federal funds for lobbying activities by recipients of federal contracts, grants, loans, or cooperative agreements exceeding $100,000. This regulation is particularly significant for higher education institutions that receive substantial federal funding through research grants, student aid programs, and other federal assistance.
INSERT INTO public.regulations VALUES (38, 'copeland-anti-kickback-act', 'Copeland Anti-Kickback Act', 'Contracts & Procurement', '18 U.S.C. § 874; 40 U.S.C. § 3145', NULL, 'Prohibits inducement of kickbacks from public works employees.
INSERT INTO public.regulations VALUES (39, 'davis-bacon-act', 'Davis-Bacon Act', 'Contracts & Procurement', '40 U.S.C. §§ 3141- 3144, 3146, 3147', NULL, 'All laborers and mechanics employed by contractors or subcontractors to work on construction contracts in excess of $2,000 financed by federal assistance funds must be paid wages not less than those established for the locality of the project (prevailing wage rates) by the Department of Labor. In construction contracts subject to the Davis-Bacon Act, institutions must include a provision requiring that the contractor or subcontractor comply with the requirements of the Act and applicable regulations.', '', 'Contracts & Procurement', 'federal', true, NULL, NULL, '2026-06-25 15:35:10.198292', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Davis-Bacon Act, codified at 40 U.S.C. §§ 3141-3144, 3146, and 3147, mandates prevailing wage requirements for federally funded construction projects exceeding $2,000. This legislation, originally enacted in 1931 and significantly amended by the Davis-Bacon Act Reform Act of 1988, applies directly to higher education institutions receiving federal construction assistance through programs such as Title III HBCU Capital Financing, NSF research facility grants, and other federal infrastructure funding.
INSERT INTO public.regulations VALUES (40, 'e-verify-executive-order-13465-amending-executive-', 'E-Verify Executive Order 13465-Amending Executive Order 12989', 'Contracts & Procurement', 'Executive Order 13465; 8 U.S.C. § 1324a', NULL, 'For federal contracts of more than $100,000 and subcontracts greater than $3,000, the University must utilize the E-Verify electronic system to confirm the employees working on those contracts/subcontracts are lawfully eligible to work in the U.S.', '', 'Contracts & Procurement', 'federal', true, NULL, NULL, '2026-06-25 15:35:10.22769', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'Executive Order 13465, issued in 2008 and codified at 8 CFR 274a.1, amends Executive Order 12989 to mandate E-Verify usage for federal contractors, significantly impacting higher education institutions receiving federal contracts. This regulation requires universities with federal contracts exceeding $100,000 to utilize the Department of Homeland Security''s E-Verify electronic employment eligibility verification system for all employees working on covered contracts and subcontracts over $3,000.
INSERT INTO public.regulations VALUES (41, 'higher-education-act-foreign-gift-and-contract-rep', 'Higher Education Act: Foreign Gift and Contract Reports', 'Fundraising & Development', '20 U.S.C. § 1011f', NULL, 'Whenever an institution is owned or controlled by a foreign source, or receives gifts from or enter into contracts with a foreign source totaling more than $250,000 within a calendar year, the institution shall file a disclosure report with the Secretary of Education on January 31 or July 31, whichever is sooner. This page serves as a repository for all relevant data, information, guidance, and training related to the required foreign gift and contract reporting.', '', 'Fundraising & Development', 'federal', true, NULL, NULL, '2026-06-25 15:35:10.256821', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Higher Education Act Foreign Gift and Contract Reporting requirement, codified at 20 U.S.C. § 1011f and implemented through 34 CFR Part 117, mandates comprehensive disclosure of foreign financial relationships by institutions of higher education. This federal transparency initiative requires institutions to report foreign gifts and contracts valued at $250,000 or more within a calendar year, ensuring public accountability and national security oversight of foreign influence in American higher education.
INSERT INTO public.regulations VALUES (42, 'small-business-act-and-small-business-investment-a', 'Small Business Act and Small Business Investment Act of 1958', 'Contracts & Procurement', '15 U.S.C.  631-657s', NULL, 'Any contractor receiving a contract with a value greater than the simplified acquisition threshold must agree in the contract that small business, veteran-owned small business, service-disabled veteran-owned small business, HUBZone small business, small disadvantaged business, and women-owned small business concerns will have the maximum practicable opportunity to participate in contract performance consistent with its efficient performance.
INSERT INTO public.regulations VALUES (43, 'trade-sanctions-reform-and-export-enhancement', 'Trade Sanctions Reform and Export Enhancement', 'Contracts & Procurement', '22 U.S.C. §§ 7201-7211', NULL, 'Assets Control Regulations of the U.S. Department of Treasury require persons subject to U.S. jurisdiction to have a license to engage in certain transactions related to travel to, from and within regulated countries.', '', 'Contracts & Procurement', 'federal', true, NULL, NULL, '2026-06-25 15:35:10.334772', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Trade Sanctions Reform and Export Enhancement Act (TSREEA) of 2000, codified at 22 U.S.C. §§ 7201-7211, establishes comprehensive regulations governing international trade and academic exchanges involving sanctioned countries. The Act significantly impacts higher education institutions by requiring compliance with Treasury''s Office of Foreign Assets Control (OFAC) regulations under 31 CFR Chapter V.
INSERT INTO public.regulations VALUES (44, 'non-retaliation-for-disclosure-of-compensation-inf', 'Non-Retaliation for Disclosure of Compensation Information', 'Contracts & Procurement,Recruitment Hiring & Termination', 'Executive Order 13665', NULL, 'Federal contractors and subcontractors may not fire or otherwise discriminate against any employee or applicant for discussing, disclosing, or inquiring about his or her compensation or that of another employee or applicant.
INSERT INTO public.regulations VALUES (45, 'copyright-act', 'Copyright Act', 'Copyright & Trademark', '17 U.S.C. §§ 101-1332', NULL, 'Protects the rights of authors from unauthorized reproduction/adaptation/performance/display/distribution of protected works of authorship, including computer software, books, journals etc. Software licenses required.
INSERT INTO public.regulations VALUES (47, 'digital-millennium-copyright-act-dmca', 'Digital Millennium Copyright Act (DMCA)', 'Information Technology', 'Public Law 105-304', NULL, 'Imposes rules prohibiting the circumvention of technological protection measures.
INSERT INTO public.regulations VALUES (49, 'small-webcasters-settlement-act-of-2002', 'Small Webcasters Settlement Act of 2002', 'Copyright & Trademark', 'Public Law No. 107-321; 17 U.S.C. §§ 101 & 114', NULL, 'Applies to "Noncommercial Webcasters" and to "Small Commercial Webcasters."
INSERT INTO public.regulations VALUES (50, 'technology-education-and-copyright-harmonization-a', 'Technology Education and Copyright Harmonization Act (TEACH ACT) of 2002', 'Copyright & Trademark', 'Public Law No. 107-273; 17 U.S. Code § 110 - Limitations on exclusive rights: Exemption of certain performances and displays', NULL, 'Permits an instructor to display virtually all types of works during on-line instruction at accredited nonprofit educational institutions without consent of copyright owner, provided that instruction is mediated by an instructor, transmission is intended only for students enrolled in course, and measures are employed to prevent redistribution of transmission and prevent its retention for longer than the class session.', '', 'Intellectual Property', 'federal', true, NULL, NULL, '2026-06-25 15:35:10.681472', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Technology Education and Copyright Harmonization Act (TEACH Act) of 2002, codified at 17 U.S.C. § 110(2), significantly expanded copyright exemptions for accredited nonprofit educational institutions conducting distance education. This legislation amended the Copyright Act of 1976 to address the growing need for digital instruction while balancing copyright holders'' rights with educational access.
INSERT INTO public.regulations VALUES (51, 'fair-housing-act-section-6', 'Fair Housing Act, Section 6', 'Disabilities', '42 U.S.C. 3604(3)', NULL, 'The Joint Statement of the Department of Housing and Urban Development and the Department of Justice Reasonable Accommodations under the Fair Housing Act  requires housing providers to allow residents to have assistance animals reside with them.', '', 'Civil Rights', 'federal', true, NULL, NULL, '2026-06-25 15:35:10.709402', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Fair Housing Act''s reasonable accommodation provisions, codified at 42 U.S.C. § 3604(f)(3)(B), mandate that higher education institutions providing housing accommodate disabled students by permitting assistance animals, even when institutional policies prohibit pets. This federal civil rights law extends beyond traditional housing to encompass university-owned dormitories, apartments, and other residential facilities.
INSERT INTO public.regulations VALUES (52, 'patient-protection-and-affordable-care-act-section', 'Patient Protection and Affordable Care Act (Section 1557)', 'Disabilities', '42 U.S.C. 18116', NULL, 'Subject entities must provide auxiliary aids for patients with disabilities and ensure health-related programs or activities provided through electronic/IT means are accessible to individuals with disabilities.', '', 'Civil Rights', 'federal', true, NULL, NULL, '2026-06-25 15:35:10.740471', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'Section 1557 of the Patient Protection and Affordable Care Act (42 U.S.C. § 18116) serves as the primary federal civil rights law prohibiting discrimination on the basis of race, color, national origin, sex, age, or disability in covered health programs or activities. For higher education institutions, this regulation applies to any health-related program or activity that receives federal financial assistance, including student health centers, counseling services, health insurance plans, and health-related academic programs.
INSERT INTO public.regulations VALUES (53, 'the-family-and-medical-leave-act-of-1993', 'The Family and Medical Leave Act of 1993', 'Discrimination', '29 U.S.C. §§ 2601-2654', NULL, 'Entitles eligible employees of covered employers to take unpaid, job-protected leave for specified family and medical reasons with continuation of group health insurance coverage under the same terms and conditions as if the employee had not taken leave.
INSERT INTO public.regulations VALUES (54, 'equal-employment-opportunity', 'Equal Employment Opportunity', 'Discrimination', 'Executive Order 11246 (OFCCP)', NULL, 'Federal contractors must not discriminate in employment decisions on the basis of race, religion, color, sex, or national origin.
INSERT INTO public.regulations VALUES (55, 'equal-employment-of-veterans', 'Equal Employment of Veterans', 'Diversity/Affirmative Action', '38 U.S.C. §§ 4211-4215', NULL, 'For federal subcontracts of $100,000 or more the University shall include in each of its subcontracts a clause that the subcontractor will not discriminate against any employee or applicant for employment because he or she is a special disabled veteran, veteran of the Vietnam era, recently separated veteran, or other protected veteran in regard to any position for which the employee or applicant for employment is qualified.
INSERT INTO public.regulations VALUES (56, 'genetic-information-non-discrimination-act-of-2008', 'Genetic Information Non-Discrimination Act of 2008', 'Diversity/Affirmative Action', 'Public Law No. 110-233', NULL, 'Prohibits use of genetic information in employment decision-making.
INSERT INTO public.regulations VALUES (57, 'lilly-ledbetter-fair-pay-act-of-2009', 'Lilly Ledbetter Fair Pay Act of 2009', 'Diversity/Affirmative Action', 'Public Law No. 111-2', NULL, 'An individual subjected to compensation discrimination under Title VII of the Civil Rights Act of 1964, the Age Discrimination in Employment Act of 1967, or the Americans with Disabilities Act of 1990 may file a charge within 180 (or 300) days of any of the following: 1) when a discriminatory compensation decision or other discriminatory practice affecting compensation is adopted; 2) when the individual becomes subject to a discriminatory compensation decision or other discriminatory practice affecting compensation; or 3) when the individual''s compensation is affected by the application of a discriminatory compensation decision or other discriminatory practice, including each time the individual receives compensation that is based in whole or part on such compensation decision or other practice.
INSERT INTO public.regulations VALUES (58, 'the-equal-pay-act-of-1963', 'The Equal Pay Act of 1963', 'Discrimination', '29 U.S.C. § 206(d)', NULL, 'Prohibits sex-based wage discrimination between men and women in the same establishment who perform jobs that require substantially equal skill, effort and responsibility under similar working conditions.', '', 'Civil Rights', 'federal', true, NULL, NULL, '2026-06-25 15:35:10.955944', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Equal Pay Act of 1963, codified at 29 U.S.C. § 206(d), represents a landmark federal statute prohibiting sex-based wage discrimination in American workplaces, including higher education institutions. This legislation amends the Fair Labor Standards Act and establishes the fundamental principle that employers cannot discriminate in compensation between male and female employees performing substantially equal work.
INSERT INTO public.regulations VALUES (59, 'title-vii-of-the-civil-rights-act-of-1964', 'Title VII of the Civil Rights Act of 1964', 'Employment Non-Discrimination', '42 U.S.C. §§ 2000e-2000e-17', NULL, 'Title VII of the Civil Rights Act of 1964 prohibits employment discrimination based on race, color, religion, sex, and national origin. For higher education institutions as employers, this includes non-discriminatory hiring practices, prevention of workplace harassment, religious accommodations, compensation equity, and compliance with EEOC reporting requirements.', 'TITLE VII COMPLIANCE REQUIREMENTS:
INSERT INTO public.regulations VALUES (60, 'uniformed-services-employment-and-reemployment-rig', 'Uniformed Services Employment and Reemployment Rights Act (USERRA)', 'Employee Benefits', '38 U.S.C. § 4301-4335', NULL, 'Seeks to ensure that members of the uniformed services are entitled to return to their civilian employment upon completion of their service.
INSERT INTO public.regulations VALUES (61, 'pregnant-workers-fairness-act-pwfa', 'Pregnant Workers Fairness Act (PWFA)', 'Discrimination,Human Resources', '42 U.S.C. Chapter 21G', NULL, '<li style="list-style-type: none;">
INSERT INTO public.regulations VALUES (62, 'affirmative-action-equal-employment-opportunity', 'Affirmative Action/Equal Employment Opportunity', 'Diversity/Affirmative Action', 'Executive Order 11246', NULL, 'Affirmative action must be taken by covered employers to recruit and advance qualified minorities, women, persons with disabilities, and covered veterans.', '', 'Civil Rights', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.139748', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'Executive Order 11246, signed by President Lyndon B. Johnson in 1965 and subsequently amended, establishes comprehensive affirmative action and equal employment opportunity requirements for federal contractors, including higher education institutions that receive federal contracts or subcontracts. This foundational civil rights directive, codified at 41 C.F.R. Parts 60-1 through 60-741, mandates that covered employers take affirmative action to ensure equal employment opportunities for minorities, women, individuals with disabilities, and covered veterans. For colleges and universities that serve as federal contractors, compliance with Executive Order 11246 represents a critical legal obligation that extends far beyond mere non-discrimination policies to encompass proactive measures designed to identify and eliminate employment barriers while promoting inclusive hiring and advancement practices.
INSERT INTO public.regulations VALUES (63, 'age-discrimination-employment-act-of-1967', 'Age Discrimination in Employment Act of 1967', 'Diversity/Affirmative Action', '29 U.S.C. §§ 621-634', NULL, 'It is unlawful for a university to fail to hire, discharge, segregate, classify, or otherwise discriminate against any individual with respect to compensation, terms, conditions or privileges of employment because of age.', '', 'Civil Rights', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.168086', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Age Discrimination in Employment Act of 1967 (ADEA), codified at 29 U.S.C. §§ 621-634, prohibits employment discrimination against individuals who are 40 years of age or older in universities and other covered employers. This federal statute applies to higher education institutions with 20 or more employees and encompasses all aspects of the employment relationship, including hiring, termination, promotion, compensation, job assignments, training opportunities, and benefits administration.
INSERT INTO public.regulations VALUES (64, 'immigration-and-nationality-act', 'Immigration and Nationality Act', 'Recruitment Hiring & Termination', '8 U.S.C. §§ 1101-1537', NULL, 'The INA, as amended, sets forth the laws governing the admission and employment of foreign nationals in the United States, including provisions that address employment eligibility and employment verification.', '', 'Human Resources', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.195935', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, '
INSERT INTO public.regulations VALUES (65, 'veterans-employment-emphasis-under-federal-contrac', 'Veterans’ employment emphasis under Federal contracts', 'Diversity/Affirmative Action', '38 U.S.C § 4212', NULL, 'No description available', '', 'Civil Rights', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.224293', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'Veterans'' employment emphasis under federal contracts, codified at 38 U.S.C. § 4212, establishes mandatory affirmative action requirements for federal contractors, including higher education institutions receiving federal contracts exceeding $150,000. This regulation, implemented through 41 CFR Part 60-250, requires covered contractors to take affirmative action to employ and advance qualified covered veterans, including disabled veterans, recently separated veterans, active duty wartime or campaign badge veterans, and Armed Forces service medal veterans.
INSERT INTO public.regulations VALUES (75, 'clean-water-act', 'Clean Water Act', 'Environmental Health and Safety', '33 U.S.C. §§ 1251-1387', NULL, 'Establishes the basic structure for regulating discharges of pollutants into the waters of the United States and regulating quality standards for surface waters. Facilities are governed by local wastewater pretreatment standards issued by local wastewater treatment plants.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.507989', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Clean Water Act (CWA), codified at 33 U.S.C. §§ 1251-1387, establishes the fundamental framework for regulating pollutant discharges into United States waters and maintaining surface water quality standards. For higher education institutions, compliance is mandatory under the Act''s broad jurisdictional scope covering all facilities that discharge pollutants to waters of the United States or local treatment systems.
INSERT INTO public.regulations VALUES (66, 'cafeteria-plan-regulations', 'Cafeteria Plan Regulations', 'Employee Benefits', '26 U.S.C. § 125; 26 CFR § 1.125', NULL, 'A cafeteria plan is a written plan that allows employees to exclude from gross income certain types of employer provided benefits, such as accident and health insurance, group term and life insurance, and benefits under a dependent care assistance program.
INSERT INTO public.regulations VALUES (67, 'consolidated-omnibus-budget-reconciliation-act-cob', 'Consolidated Omnibus Budget Reconciliation Act (COBRA)', 'Employee Benefits', 'Public Law No. 99-272', NULL, 'Enables employees and their families to continue health care coverage under an employer''s group health plan even after they experience an event that would otherwise end their coverage (e.g. layoff, termination, decrease in hours, divorce, etc.).', '', 'Human Resources', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.280929', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Consolidated Omnibus Budget Reconciliation Act (COBRA), codified at 29 U.S.C. §§ 1161-1168 and implemented through 29 CFR § 2590.606, mandates that higher education institutions with 20 or more employees provide continuation coverage options for group health plans. This federal law ensures that employees, their spouses, and dependent children can maintain health insurance coverage following qualifying events that would otherwise terminate their eligibility.
INSERT INTO public.regulations VALUES (68, 'employee-retirement-income-security-act-of-1974-er', 'Employee Retirement Income Security Act of 1974 (ERISA)', 'Retirement', '29 U.S.C. Chapter 18', NULL, 'Sets minimum standards for participation, vesting, benefit accrual and funding pension plans.
INSERT INTO public.regulations VALUES (69, 'medicare-medicaid-and-schip-extension-act-of-2007', 'Medicare, Medicaid, and SCHIP Extension Act of 2007', 'Employee Benefits', 'Public Law No. 110-173', NULL, 'The University, as a provider of self-insured group health and worker''s compensation plans, must determine whether a claimant is entitled to benefits under Medicare on any basis, and if so, must submit to the Secretary of the Department of Health and Human Services the claimant''s identity and other information (e.g. SSNs, date of birth, sex, and address) specified by the Secretary for coordination of benefits and recovery claims purposes.', '', 'Human Resources', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.337472', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Medicare, Medicaid, and SCHIP Extension Act of 2007 (MMSEA), codified at 42 U.S.C. § 1395y(b)(8), establishes mandatory reporting requirements for group health plan sponsors, including higher education institutions offering self-insured health plans. Under Section 111 of MMSEA, universities must report settlement, judgment, award, or other payment information to the Centers for Medicare & Medicaid Services (CMS) to facilitate Medicare Secondary Payer (MSP) coordination and recovery efforts.
INSERT INTO public.regulations VALUES (70, 'patient-protection-and-affordable-care-act', 'Patient Protection and Affordable Care Act', 'Employee Benefits', 'Public Law No. 111-148; 42 U.S.C §§ 18001-18122', NULL, 'Beginning in 2015, under IRC 4980H applicable large employers (generally those with 50 or more employees) must pay a tax penalty if
INSERT INTO public.regulations VALUES (71, 'the-veterans-readjustment-benefits-act', 'The Veterans’ Readjustment Benefits Act', 'Employee Benefits', '38 U.S.C. §§ 4211-4214', NULL, 'Provides the rights, benefits, and obligations of persons absent from employment for military service.', '', 'Human Resources', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.39341', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Veterans'' Readjustment Benefits Act, codified in 38 U.S.C. §§ 4211-4214, establishes comprehensive employment protections and benefits for veterans and service members, with significant implications for higher education institutions as employers. This federal legislation ensures that individuals who serve in the uniformed services retain their employment rights and receive appropriate benefits upon return to civilian employment.
INSERT INTO public.regulations VALUES (72, 'atomic-energy-act-of-1954', 'Atomic Energy Act of 1954', 'Environmental Health and Safety', '42 U.S.C. §§ 2011-2296b-7', NULL, 'The Atomic Energy Act requires that civilian uses of nuclear materials and facilities be licensed. Under section 274 of the Act (42 U.S.C 2021), the NRC may enter into an agreement with a state for discontinuance of the NRC''s regulatory authority over some materials licensees within the state. The state must first show that its regulatory program is compatible with the NRC''s and adequate to protect public health and safety. The NRC retains authority over, among other things, nuclear power plants within the state and exports from the state.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.420147', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Atomic Energy Act of 1954 (42 U.S.C. §§ 2011-2296b-7) establishes comprehensive federal regulation of nuclear materials and facilities, requiring licensing for all civilian uses of atomic energy. For higher education institutions, this regulation is particularly relevant to universities conducting nuclear research, operating research reactors, or using radioactive materials in educational and research activities.
INSERT INTO public.regulations VALUES (73, 'chemical-facility-anti-terrorism-standards', 'Chemical Facility Anti-Terrorism Standards', 'Environmental Health and Safety', 'Executive Order 13563 and 12866', NULL, 'This rule establishes risk-based performance standards for the security of the nation''s chemical facilities.
INSERT INTO public.regulations VALUES (74, 'clean-air-act', 'Clean Air Act', 'Environmental Health and Safety', '42 U.S.C. §§ 7401-7671q', NULL, 'Regulates air emissions from stationary and mobile sources.
INSERT INTO public.regulations VALUES (76, 'comprehensive-environmental-response-compensation-', 'Comprehensive Environmental Response, Compensation, and Liability Act (CERCLA)', 'Environmental Health and Safety', '42 U.S.C. §§ 9601-9675', NULL, 'Establishes prohibitions and requirements concerning closed and abandoned hazardous waste sites;
INSERT INTO public.regulations VALUES (77, 'energy-policy-act', 'Energy Policy Act', 'Environmental Health and Safety', '42 U.S.C. §§ 13201-13574', NULL, 'Addresses energy production and contains Underground Storage Tank provisions.
INSERT INTO public.regulations VALUES (78, 'energy-reorganization-act-of-1974-as-amended', 'Energy Reorganization Act of 1974, as amended', 'Environmental Health and Safety', '42 U.S.C. § 5801 et seq.', NULL, 'Governs the handling, storage, and disposal of radioactive materials. See the General Statement of Policy and Procedures for NRC Enforcement Actions', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.664746', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Energy Reorganization Act of 1974, codified at 42 U.S.C. § 5801 et seq., established the Nuclear Regulatory Commission (NRC) and governs the civilian use of nuclear materials, including their handling, storage, and disposal at higher education institutions. This comprehensive federal statute provides the legal framework for regulating radioactive materials used in research, medical applications, and educational programs across university campuses.
INSERT INTO public.regulations VALUES (79, 'federal-insecticide-fungicide-and-rodenticide-act', 'Federal Insecticide, Fungicide and Rodenticide Act', 'Environmental Health and Safety', '7 U.S.C. §§ 136-136y', NULL, 'Provides for federal regulation of pesticide distribution, sale, and use.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.693495', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Federal Insecticide, Fungicide and Rodenticide Act (FIFRA), codified at 7 U.S.C. §§ 136-136y, establishes comprehensive federal oversight of pesticide distribution, sale, and use throughout the United States. Administered by the Environmental Protection Agency (EPA) under 40 CFR Parts 150-189, FIFRA requires registration of all pesticides before commercial distribution and mandates compliance with labeling, application, and safety requirements that directly impact higher education institutions.
INSERT INTO public.regulations VALUES (80, 'guarding-and-use-of-hand-portable-powered-tools', 'Guarding and Use of Hand & Portable Powered Tools', 'Environmental Health and Safety', '29 CFR § 1910.241-244', NULL, 'The University is responsible for the safe condition and guarding of portable powered tools/equipment (ex: saws/drills/drivers/sanders/grinders/ pneumatic tools/explosive fasteners, etc.) including tools furnished by employees.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.721369', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The regulation governing guarding and use of hand and portable powered tools in higher education institutions derives its authority from the Occupational Safety and Health Act of 1970 (29 U.S.C. § 651 et seq.) and corresponding federal regulations under 29 CFR Part 1910, Subpart P - Hand and Portable Powered Tools and Other Hand-Held Equipment. Universities must comply with comprehensive safety standards that protect faculty, staff, students, and contractors from workplace hazards associated with powered tool operations.
INSERT INTO public.regulations VALUES (81, 'hazardous-materials-transportation-act', 'Hazardous Materials Transportation Act', 'Information Technology', '49 U.S.C. §§ 5101-5128', NULL, 'The University must properly dispose of computers and electrical equipment containing hazardous materials or the University is subject to fines and penalties.', '', 'Information Technology', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.750757', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Hazardous Materials Transportation Act (HMTA), codified at 49 U.S.C. §§ 5101-5128, establishes comprehensive federal oversight of hazardous materials transportation to protect public safety and property. The Department of Transportation (DOT) implements this statute through extensive regulations at 49 CFR Parts 100-185, creating binding obligations for higher education institutions that handle, store, or transport hazardous materials.
INSERT INTO public.regulations VALUES (82, 'hazardous-and-solid-waste-amendments-of-1984', 'Hazardous and Solid Waste Amendments of 1984', 'Environmental Health and Safety', '42 U.S.C. §§ 6921-6939g', NULL, 'Regulation of underground storage tanks and land-based disposal of hazardous substances.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.778707', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Hazardous and Solid Waste Amendments of 1984 (HSWA), codified at 42 U.S.C. §§ 6921-6939g, significantly strengthened the Resource Conservation and Recovery Act (RCRA) by establishing comprehensive regulations for underground storage tanks (USTs) and restricting land disposal of hazardous wastes. For higher education institutions, HSWA compliance is critical given the prevalence of USTs for fuel storage, heating oil, and chemical storage across campus facilities.
INSERT INTO public.regulations VALUES (83, 'housing-urban-development-lead-based-paint-poisoni', 'Housing & Urban Development Lead Based Paint Poisoning in Certain Residential Structures', 'Environmental Health and Safety', '42 U.S.C. § 4852d', NULL, 'The University must provide lessees with a federally-approved pamphlet on lead poisoning prevention.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.807385', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Housing and Urban Development Lead-Based Paint Poisoning Prevention requirements, codified under 42 U.S.C. § 4852d and implemented through 24 CFR Part 35, establish mandatory disclosure and educational obligations for higher education institutions that lease residential housing constructed before 1978. This federal regulation, part of the Residential Lead-Based Paint Hazard Reduction Act of 1992, requires universities to provide comprehensive lead hazard information to all residential lessees.
INSERT INTO public.regulations VALUES (84, 'mandatory-reporting-of-greenhouse-gases', 'Mandatory Reporting of Greenhouse Gases', 'Environmental Health and Safety', '40 CFR Part 98', NULL, 'Implemented under the Environmental Protection Agency''s (EPA) powers under the Clean Air Act, the rule requires that the university submit an annual report on the university''s greenhouse gas emissions. Gases covered by the rule include carbon dioxide (CO2), methane (CH4), nitrous oxide (N2O), hydro fluorocarbons (HFC), per fluorocarbons (PFC), sulfur hexafluoride (SF6) and other fluorinated gases and hydro fluorinated ethers.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.835711', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The EPA Greenhouse Gas Reporting Program (GHGRP), established under the Clean Air Act and codified at 40 CFR Part 98, mandates comprehensive annual reporting of greenhouse gas emissions from large-scale stationary sources, including higher education institutions operating qualifying facilities. This federal regulation, effective since 2010, requires universities with facilities that emit 25,000 metric tons CO2 equivalent (CO2e) or more annually to submit detailed emissions data to the Environmental Protection Agency.
INSERT INTO public.regulations VALUES (85, 'motor-carrier-act-of-1980', 'Motor Carrier Act of 1980', 'Environmental Health and Safety', '49 U.S.C. § 13101 et seq.', NULL, 'Institutions are liable for any pollution-related incident that occurs during the transportation of hazardous material.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.864568', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Motor Carrier Safety Act of 1980, codified at 49 U.S.C. § 31101 et seq., established comprehensive federal oversight of commercial motor vehicle operations, including the transportation of hazardous materials. While primarily focused on interstate commerce, this legislation significantly impacts higher education institutions that engage in or contract for the transportation of hazardous substances for research, laboratory operations, or facility maintenance activities.
INSERT INTO public.regulations VALUES (86, 'national-emission-standards-for-hazardous-air-poll', 'National Emission Standards for Hazardous Air Pollutants (NESHAP)', 'Environmental Health and Safety', '40 CFR Part 61 (NESHAP)', NULL, 'The asbestos NESHAP regulations specify work practices for asbestos to be followed during demolitions and renovations of all structures, installations, and buildings (excluding residential buildings that have four or fewer dwelling units). The regulations require the owner of the building or the operator to notify the appropriate state agency before any demolition, or before any renovations of buildings that could contain a certain threshold amount of asbestos or asbestos-containing material. In addition, particular manufacturing and fabricating operations either cannot emit visible emissions into the outside air or must follow air-cleaning procedures, as well as follow certain requirements when removing asbestos-containing waste.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:11.893125', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The National Emission Standards for Hazardous Air Pollutants (NESHAP) for asbestos, codified at 40 CFR Part 61, Subpart M, establishes comprehensive federal standards governing asbestos management during demolition and renovation activities at higher education institutions. This regulation derives its authority from the Clean Air Act, 42 U.S.C. § 7412, and applies to all structures containing regulated asbestos-containing material (RACM).
INSERT INTO public.regulations VALUES (87, 'osha-asbestos-in-construction-standard', 'OSHA Asbestos in Construction Standard', 'Environmental Health and Safety', '29 CFR § 1926.1101', NULL, 'Applies to construction only. No employee may be exposed to an airborne concentration of asbestos in excess of 0.1 fiber per cubic cm of air as an 8 hour time-weighted average.
INSERT INTO public.regulations VALUES (88, 'osha-asbestos-in-general-industry-standard', 'OSHA Asbestos in General Industry Standard', 'Environmental Health and Safety', '29 CFR § 1910.1001', NULL, 'The University must ensure that no employee is exposed to an airborne concentration of asbestos in excess of 0.1 fiber per cubic centimeter of air as an eight hour time-weighted average. &nbsp;Applies to occupational exposure other than construction.
INSERT INTO public.regulations VALUES (89, 'osha-enforcement-guidance-for-personal-protective-', 'OSHA Enforcement Guidance for Personal Protective Equipment (PPE) in General Industry', 'Environmental Health and Safety', '29 CFR § 1910.132-138 (PPE)', NULL, 'OSHA requires the use of Personal Protective Equipment (PPE) to reduce employee exposure to hazards when engineering and administrative controls are not feasible or effective in reducing these exposures to acceptable levels.
INSERT INTO public.regulations VALUES (90, 'osha-lead-in-construction-standard', 'OSHA Lead in Construction Standard', 'Environmental Health and Safety', '29 CFR § 1926.62', NULL, 'Applies to exposure to lead during construction only.
INSERT INTO public.regulations VALUES (91, 'osha-lead-in-general-industry-standard', 'OSHA Lead in General Industry Standard', 'Environmental Health and Safety', '29 CFR § 1910.1025', NULL, 'Applies to occupational exposure to lead by employees in non-construction setting.
INSERT INTO public.regulations VALUES (92, 'osha-welding-cutting-and-brazing', 'OSHA Welding, Cutting, and Brazing', 'Environmental Health and Safety', '29 CFR § 1910.251-255', NULL, 'Before cutting/welding can be permitted, the area must be inspected by the individual responsible for authorizing cutting/welding operations, and who must designate precautions to be followed in granting authorization, preferably in the form of a written permit.
INSERT INTO public.regulations VALUES (93, 'osha-bloodborne-pathogens-standard', 'OSHA – Bloodborne Pathogens Standard', 'Environmental Health and Safety', '29 CFR § 1910.1030', NULL, 'The university must maintain a written exposure control plan and provide appropriate instruction on precautions to all workers who might become exposed to blood or other potentially infectious materials.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:12.1586', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Occupational Safety and Health Administration (OSHA) Bloodborne Pathogens Standard, codified at 29 CFR § 1910.1030, mandates comprehensive protections for workers who face occupational exposure to human blood and other potentially infectious materials (OPIM). Established under the authority of the Occupational Safety and Health Act of 1970 (29 U.S.C. § 651 et seq.), this standard applies extensively to higher education institutions including universities, medical schools, research facilities, and vocational training programs.
INSERT INTO public.regulations VALUES (94, 'osha-s-emergency-action-plan-standard', 'OSHA’s  Emergency Action Plan Standard', 'Environmental Health and Safety', '29 CFR § 1910.38', NULL, 'The University must have a written emergency action plan kept in the workplace and available for employee review upon request.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:12.186806', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Occupational Safety and Health Administration''s Emergency Action Plan Standard, codified at 29 CFR § 1910.38, establishes mandatory requirements for employers, including higher education institutions, to develop, implement, and maintain comprehensive written emergency action plans. This federal regulation represents a critical component of workplace safety compliance for colleges and universities, requiring institutions to prepare for various emergency scenarios that could threaten the safety and welfare of employees, students, and visitors on campus.
INSERT INTO public.regulations VALUES (95, 'osha-s-occupational-noise-exposure-standard', 'OSHA’s  Occupational Noise Exposure Standard', 'Environmental Health and Safety', '29 C.F.R 1910.95', NULL, 'The OSHA noise exposure standards define two action levels at which worker protection must be provided and used, based on the 8 hour time weighted average of noise levels that the worker is exposed to throughout the day.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:12.216', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Occupational Safety and Health Administration''s Occupational Noise Exposure Standard, codified at 29 C.F.R. § 1910.95, establishes comprehensive requirements for protecting workers from hazardous noise exposure in the workplace. This regulation applies broadly to higher education institutions, encompassing faculty, staff, and student workers who may be exposed to potentially harmful noise levels during the course of their employment or educational activities. The standard recognizes that prolonged exposure to excessive noise can result in permanent hearing loss and establishes specific action levels and permissible exposure limits designed to prevent occupational hearing loss.
INSERT INTO public.regulations VALUES (96, 'osha-s-occupational-exposure-to-hazardous-chemical', 'OSHA’s Occupational Exposure to Hazardous Chemicals in Laboratories Standard', 'Environmental Health and Safety', '29 CFR § 1910.1450', NULL, 'Provides strict guidelines for laboratory safety. Key components of the laboratory standard include having a chemical hygiene plan and providing employees with training and information. The laboratory standard applies to labs that:
INSERT INTO public.regulations VALUES (97, 'oil-pollution-act', 'Oil Pollution Act', 'Environmental Health and Safety', '33 U.S.C.§§ 2701-2762', NULL, 'Regulation requires container inspection and integrity, testing, recordkeeping, annual training for employees who handle oil, and annual discharge prevention briefings.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:12.273231', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Oil Pollution Act (OPA) of 1990, codified at 33 U.S.C. §§ 2701-2762, establishes comprehensive liability and prevention requirements for oil pollution incidents in U.S. waters. Higher education institutions operating facilities that store, handle, or transfer oil products must comply with specific provisions under this federal environmental statute.
INSERT INTO public.regulations VALUES (98, 'residential-lead-based-paint-hazard-reduction-act-', 'Residential Lead-Based Paint Hazard Reduction Act of 1992', 'Environmental Health and Safety', '42 U.S.C. § 4851 et seq.', NULL, 'Regulations apply to owners of more than four residential housing units built before 1978.
INSERT INTO public.regulations VALUES (99, 'resource-conservation-and-recovery-act', 'Resource Conservation and Recovery Act', 'Environmental Health and Safety', '42 U.S.C. §§ 6901-6992k', NULL, 'Gives the EPA authority to control hazardous waste generation, transportation, treatment, storage and disposal.
INSERT INTO public.regulations VALUES (139, 'controlling-the-assault-of-non-solicited-pornograp', 'Controlling the Assault of Non-Solicited Pornography And Marketing Act of 2003 (CAN-SPAM Act)', 'Information Technology', '15 U.S.C. §§ 7701-7713', NULL, 'Prohibits the inclusion of deceptive or misleading information and subject headings, requires identifying information such as a return address in email messages, and prohibits sending emails to a recipient after an explicit response that the recipient does not want to continue receiving messages.
INSERT INTO public.regulations VALUES (100, 'standards-for-the-management-of-used-oil', 'Standards For the Management of Used Oil', 'Environmental Health and Safety', '40 CFR Part 279', NULL, 'Covers the standards for used oil storage, recordkeeping, labeling, off-site shipments, recycling, etc.', '', 'Environmental Health & Safety', 'federal', true, NULL, NULL, '2026-06-25 15:35:12.359853', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Standards for the Management of Used Oil, codified under 40 CFR Part 279, establishes comprehensive federal requirements for the proper handling, storage, and disposal of used oil across all sectors, including higher education institutions. This regulation, promulgated under the Resource Conservation and Recovery Act (RCRA) at 42 U.S.C. § 6901 et seq., applies to universities operating motor vehicle fleets, maintenance facilities, laboratories, or any operations generating used oil.
INSERT INTO public.regulations VALUES (101, 'the-public-health-security-and-bioterrorism-prepar', 'The Public Health Security and Bioterrorism Preparedness and Response Act', 'Environmental Health and Safety', '18 U.S.C. § 175b', NULL, 'All colleges and universities that possess select agents, which are certain biological agents and toxins, need to register with the Secretary of the U.S. Department of Health and Human Services.
INSERT INTO public.regulations VALUES (102, 'toxic-substances-control-act', 'Toxic Substances Control Act', 'Environmental Health and Safety', '15 U.S.C. § 2601-2629', NULL, 'Regulates the use and disposal of certain chemicals, including PCBs used in electrical transformers. Must comply with regulations concerning use, service, storage, and disposal of transformers containing PCBs.
INSERT INTO public.regulations VALUES (103, 'acts-affecting-a-personal-financial-interest', 'Acts Affecting a Personal Financial Interest', 'Ethics', '18 U.S.C. § 208', NULL, 'Prohibits an executive branch employee from participating personally and substantially in a particular Government matter that will affect his own financial interests, as well as the financial interests of certain individuals with whom he has ties outside the Government.', '', 'Ethics & Governance', 'federal', true, NULL, NULL, '2026-06-25 15:35:12.444286', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, '18 U.S.C. § 208 establishes comprehensive conflict of interest prohibitions for executive branch employees, including those at federally-funded higher education institutions. This criminal statute prohibits government employees from participating personally and substantially in particular government matters that would affect their financial interests or those of specified family members, business partners, and affiliated organizations.
INSERT INTO public.regulations VALUES (104, 'bribery-of-public-officials-and-witnesses', 'Bribery of Public Officials and Witnesses', 'Ethics', '18 U.S.C. § 201', NULL, 'Prohibits public officials from accepting bribes or gratuities to influence their Government actions.', '', 'Ethics & Governance', 'federal', true, NULL, NULL, '2026-06-25 15:35:12.473694', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The federal prohibition against bribery of public officials and witnesses, codified in 18 U.S.C. § 201, establishes comprehensive criminal penalties for corrupt practices involving government personnel and judicial proceedings. This statute applies broadly to higher education institutions that interact with federal officials, receive federal funding, or participate in government programs.
INSERT INTO public.regulations VALUES (105, 'compensation-to-members-of-congress-officers-other', 'Compensation to Members of Congress, Officers, Others in Matters Affecting the Government', 'Ethics', '18 U.S.C. § 203', NULL, 'Prohibits compensation for representational activities involving certain matters in which the United States is a party or has a direct and substantial interest.', '', 'Ethics & Governance', 'federal', true, NULL, NULL, '2026-06-25 15:35:12.501342', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Compensation to Members of Congress, Officers, Others in Matters Affecting the Government regulation, codified at 18 U.S.C. § 203, establishes comprehensive prohibitions against certain compensated representational activities involving federal matters. This criminal statute applies to Members of Congress, officers and employees of the United States, and members of the uniformed services, creating significant compliance obligations for higher education institutions engaging these individuals.
INSERT INTO public.regulations VALUES (106, 'ethics-in-government-act-amended-by-ethics-reform-', 'Ethics in Government Act (Amended by Ethics Reform Act and Honest Leadership and Open Government Act of 2007)', 'Ethics', '5 U.S.C. § 7353', NULL, 'Members of Congress and officers and employees of the executive, legislative, and judicial branches are barred from soliciting or accepting anything of value from anyone: (1) seeking official action from, doing business with, or conducting activities regulated by the individual''s employing entity or (2) whose interests may be substantially affected by the performance or nonperformance of the individual''s official duties.
INSERT INTO public.regulations VALUES (107, 'house-and-senate-gift-ban-and-ethics-rules', 'House and Senate Gift Ban and Ethics Rules', 'Lobbying and Political Activities', 'House Rule XXV; Senate Rule XXXV', NULL, 'Both the House and Senate have banned gifts from registered lobbyists or private entities that retain or employ them. Non-lobbyists can give gifts valued at less than $50, such as a meal at a briefing for a Member of Congress and their staff that is valued at less than $50 per person.', '', 'Ethics & Governance', 'federal', true, NULL, NULL, '2026-06-25 15:35:12.55872', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The House and Senate Gift Ban and Ethics Rules, codified under 2 U.S.C. § 25 and enforced through House Rule 25 and Senate Rule 35, establish comprehensive restrictions on gifts that Members of Congress and their staff may accept from outside entities. These rules directly impact higher education institutions'' engagement with federal legislators and their offices.
INSERT INTO public.regulations VALUES (108, 'outside-earned-income-and-activities', 'Outside Earned Income and Activities', 'Ethics', '5 U.S.C. app. 4 §§ 501-505', NULL, 'Sets forth the limitations on outside income and activities of certain noncareer employees, referred to as “covered noncareer employees.”', '', 'Ethics & Governance', 'federal', true, NULL, NULL, '2026-06-25 15:35:12.653814', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Outside Earned Income and Activities regulation, codified at 5 U.S.C. app. 4 §§ 501-505, establishes comprehensive restrictions on outside employment and income-generating activities for covered noncareer employees in executive branch agencies, including senior administrators at federally-chartered universities and government-affiliated higher education institutions.
INSERT INTO public.regulations VALUES (109, 'restrictions-on-former-officers-employees-and-elec', 'Restrictions on Former Officers, Employees, and Elected Officials of the Executive and Legislative', 'Ethics', '18 U.S.C. § 207', NULL, 'May limit the activities of individuals after they leave Federal Government service (or after they leave certain high-level positions).', '', 'Ethics & Governance', 'federal', true, NULL, NULL, '2026-06-25 15:35:12.682788', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Restrictions on Former Officers, Employees, and Elected Officials of the Executive and Legislative Branches, codified in 18 U.S.C. § 207, establishes comprehensive post-employment restrictions for federal government personnel to prevent conflicts of interest and maintain public trust in government operations. These regulations directly impact higher education institutions through their interactions with former federal officials who may join university administrations, serve on boards, or provide consulting services.
INSERT INTO public.regulations VALUES (140, 'internal-revenue-code-substantiation-and-disclosur', 'Internal Revenue Code: Substantiation and Disclosure Provisions', 'Fundraising & Development', '26 U.S.C. § 170', NULL, 'Substantiation and disclosure provisions apply to contributions made to tax-exempt organizations after December 31, 1993.
INSERT INTO public.regulations VALUES (110, 'salary-of-government-officials-and-employees-payab', 'Salary of Government Officials and Employees Payable Only by United States', 'Ethics', '18 U.S.C. § 209', NULL, 'Prohibits employees from being paid by someone other than the United States for doing their official Government duties.', '', 'Ethics & Governance', 'federal', true, NULL, NULL, '2026-06-25 15:35:12.711005', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, '18 U.S.C. § 209 establishes a fundamental prohibition against dual compensation for federal employees, including those working at public higher education institutions receiving federal funding. This statute prevents government employees from accepting salary, supplementary compensation, or any other payment from non-federal sources for performing their official government duties.
INSERT INTO public.regulations VALUES (111, 'arms-export-control-act-of-1976', 'Arms Export Control Act of 1976', 'General', '22 U.S.C. §§ 2751-2799aa-2', NULL, 'Your higher education institution must comply with federal export controls when conducting defense-related research or sharing technical data with foreign nationals. You must obtain appropriate licenses before disclosing controlled technical information to international students, visiting researchers, or foreign collaborators, and implement comprehensive compliance programs to avoid severe penalties.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (112, 'export-administration-act-of-1979', 'Export Administration Act of 1979', 'Export Controls', 'Export Controls Act of 2018', NULL, 'Primary statutory basis for the Export Administration Regulations, which regulate the export of certain § dual use § item, i.e. items that are capable of both civilian and military use.', '', 'Research', 'federal', true, NULL, NULL, '2026-06-25 15:35:12.767898', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Export Administration Act of 1979, codified at 50 U.S.C. § 4601 et seq., establishes the primary statutory framework for controlling exports of dual-use items and technologies that could serve both civilian and military purposes. While the original Act expired, its provisions continue under the International Emergency Economic Powers Act (50 U.S.C. § 1701) and have been modernized by the Export Control Reform Act of 2018 (50 U.S.C. § 4801 et seq.).
INSERT INTO public.regulations VALUES (113, 'foreign-assets-control-regulations', 'Foreign Assets Control Regulations', 'General', '22 U.S.C. § 7201-7211', NULL, 'Your organization must comply with economic sanctions administered by OFAC, prohibiting transactions with designated foreign nationals, entities, and sanctioned countries without proper licensing. You must screen all international parties against OFAC''s sanctions lists before engaging in research partnerships, student exchanges, donations, or study abroad programs.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (114, 'international-emergency-economic-powers-act', 'International Emergency Economic Powers Act', 'Export Controls', '50 U.S.C. §§ 1701-1707', NULL, 'Authorizes the President to declare the existence of an "unusual and extraordinary threat to the national security, foreign policy, or economy of the United States" that originates "in whole or substantial part outside the United States." It further authorizes the President, after such a declaration, to block transactions and freeze assets to deal with the threat.
INSERT INTO public.regulations VALUES (141, 'pension-protection-act', 'Pension Protection Act', 'Fundraising & Development', '26 U.S.C. § 170', NULL, 'No deduction will be allowed for the donor for a contribution of $250 or more (whether in cash or property) unless the donor has a contemporaneous written acknowledgment from the university substantiating the contribution.
INSERT INTO public.regulations VALUES (115, 'international-traffic-in-arms-regulations-itar', 'International Traffic in Arms Regulations (ITAR)', 'General', '22 U.S.C. § 2778', NULL, 'Your institution must control exports of defense-related research, technology, and services under the International Traffic in Arms Regulations. You must obtain proper licenses before sharing controlled technical data with foreign persons, implement comprehensive export control programs, and maintain detailed compliance records.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (116, 'trading-with-the-enemy-act-of-1917', 'Trading with the Enemy Act of 1917', 'General', '22 U.S.C. § 7201-7211; 50 U.S.C. 4301-4341', NULL, 'Your institution must comply with Trading with the Enemy Act restrictions when conducting international activities during times of war or national emergency. You must screen all international partners, students, and researchers against OFAC sanctions lists and obtain proper licenses for transactions with sanctioned countries or entities.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (117, 'contracts-with-third-party-servicers', 'Contracts with Third Party Servicers', 'General', '20 U.S.C. § 1094(c)', NULL, 'Your higher education institution must maintain strict oversight of third-party servicers that handle any aspect of federal Title IV student financial aid programs. You must ensure servicer eligibility, provide timely notifications to the Department of Education, and retain ultimate responsibility for Title IV compliance regardless of contracted services.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (118, 'higher-education-act-aid-application-verification', 'Higher Education Act: Aid Application Verification', 'General', 'Public Law No. 110-315', NULL, 'Your institution must establish comprehensive written policies for verifying FAFSA information when selected by the Department of Education or when applications contain conflicting data. You must obtain required documentation, complete verification before disbursing Title IV funds, and maintain clear procedures for communicating with students throughout the process.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (119, 'higher-education-act-audits', 'Higher Education Act: Audits', 'General', '20 U.S.C. § 1094(c); 34 CFR § 668.23', NULL, 'Your institution must conduct annual independent compliance audits if you participate in federal Title IV student financial assistance programs. You must ensure audits cover both Title IV program administration and general financial statements, then submit completed reports to the Department of Education within six months of your fiscal year end.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (120, 'higher-education-act-borrower-defense-to-repayment', 'Higher Education Act: Borrower Defense to Repayment', 'General', '20 U.S.C. § 1087e(h)', NULL, 'Your institution must protect against federal student loan discharge claims by ensuring accurate representations and maintaining comprehensive documentation of all student interactions. You must implement robust internal controls to prevent misconduct that could trigger borrower defense claims and potential Department of Education recovery actions.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (142, 'philanthropy-protection-act-of-1995', 'Philanthropy Protection Act of 1995', 'Fundraising & Development', 'Public Law No. 104-62', NULL, 'Requires the university to provide a disclosure statement to all annuitants in a Gift Annuity Fund and also to provide the same to all prospective donors at the time of solicitation, using a letter or pamphlet format.
INSERT INTO public.regulations VALUES (121, 'higher-education-act-cash-management', 'Higher Education Act: Cash Management', 'Financial Aid', 'Public Law No. 110-315', NULL, 'Establishes rules and procedures institutions must follow in requesting, maintaining, disbursing, and otherwise managing most Title IV funds.', '', 'Financial Aid', 'federal', true, NULL, NULL, '2026-06-25 15:35:13.022805', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Higher Education Act Cash Management regulations, codified primarily in 34 CFR Part 668 Subpart K and authorized by 20 U.S.C. § 1094, establish comprehensive requirements for institutions of higher education to properly manage Federal Student Aid (FSA) program funds. These regulations govern how colleges and universities request, receive, disburse, maintain, and account for Title IV federal student aid funds, including Pell Grants, Direct Loans, Federal Work-Study, and SEOG programs.
INSERT INTO public.regulations VALUES (122, 'higher-education-act-code-of-conduct', 'Higher Education Act: Code of Conduct', 'Fundraising & Development', '20 U.S.C. § 1094', NULL, 'An institution that participates in Title IV programs must have a code of conduct for financial aid practices that prohibits conflicts of interest, is published prominently on the university''s website, and is distributed annually to relevant personnel.', '', 'Fundraising & Development', 'federal', true, NULL, NULL, '2026-06-25 15:35:13.050962', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Higher Education Act Code of Conduct requirement, codified at 20 U.S.C. § 1094(a)(25) and implemented through 34 CFR § 668.14(b)(27), mandates that institutions participating in Title IV federal student aid programs establish and maintain comprehensive codes of conduct governing financial aid practices. This regulation emerged from concerns about conflicts of interest in student lending practices and was strengthened by the College Cost Reduction and Access Act of 2007.
INSERT INTO public.regulations VALUES (123, 'higher-education-act-cohort-default-rate', 'Higher Education Act: Cohort Default Rate', 'General', '20 U.S.C. § 1015a; 20 U.S.C. § 1085', NULL, 'Your institution must maintain federal student loan cohort default rates below regulatory thresholds to preserve Title IV federal aid eligibility. You must monitor borrower repayment performance and implement default prevention strategies to avoid losing access to Direct Loans, FFEL programs, and potentially Pell Grants.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (124, 'higher-education-act-eligibility-and-certification', 'Higher Education Act: Eligibility and Certification', 'General', 'Public Law No. 110-315; 20 U.S.C. § 1099c', NULL, 'Your higher education institution must obtain and maintain Department of Education certification to participate in federal Title IV student financial assistance programs. You must satisfy statutory eligibility requirements including accreditation, state authorization, and demonstration of administrative capability to administer Pell Grants, Federal Direct Loans, and Federal Work-Study programs.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (125, 'higher-education-act-entrance-and-exit-counseling', 'Higher Education Act: Entrance and Exit Counseling', 'General', 'Public Law No. 110-315; 20 U.S.C. § 1092', NULL, 'Your institution must provide comprehensive loan counseling to federal student aid borrowers before first disbursement and when they cease enrollment. You must deliver entrance counseling covering loan terms, responsibilities, and consequences, plus exit counseling detailing repayment options and servicer information within 30 days of triggering events.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (143, 'federal-sentencing-guidelines', 'Federal Sentencing Guidelines', 'Governance', '18 U.S.C. chapters 227-235; 28 U.S.C. chapter 58', NULL, 'The guidelines at §8B2.1 set forth the requirements for an effective compliance and ethics program for organizations. Organizations are vicariously liable under federal criminal law for acts committed by their agents. The definition of "organization" at 18 U.S.C. §18 includes non-profits such as a university.', '', 'Ethics & Governance', 'federal', true, NULL, NULL, '2026-06-25 15:35:13.789564', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Federal Sentencing Guidelines establish mandatory requirements for effective compliance and ethics programs under 18 U.S.C. § 3553(a) and chapters 227-235, with specific provisions codified in the United States Sentencing Guidelines Manual § 8B2.1. These guidelines create a framework of organizational accountability that directly applies to higher education institutions as "organizations" under 18 U.S.C. § 18, encompassing non-profit entities including universities, colleges, and educational foundations.
INSERT INTO public.regulations VALUES (126, 'higher-education-act-federal-supplemental-educatio', 'Higher Education Act: Federal Supplemental Educational Opportunity Grant Program', 'General', 'Public Law No. 110-315; 20 U.S.C. §§ 1070b- 1070b-4', NULL, 'Your institution must administer the Federal Supplemental Educational Opportunity Grant (FSEOG) program by providing need-based grants to exceptionally needy undergraduate students while contributing at least 25% matching funds. You must execute a Participation Agreement with the Department of Education, maintain separate accounting for federal funds, and implement strict internal controls for fund management and disbursement.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (127, 'higher-education-act-federal-work-study', 'Higher Education Act: Federal Work Study', 'General', 'Public Law No. 110-315; 42 U.S.C. §§ 2751-2757', NULL, 'Your institution must administer the Federal Work Study Program by providing part-time employment opportunities for students with demonstrated financial need while contributing at least 25% of student wages. You must allocate at least 7% of your FWS funding for community service positions, including at least one reading tutor position, and ensure all wages meet federal minimum wage requirements.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (128, 'higher-education-act-financial-responsibility-requ', 'Higher Education Act: Financial Responsibility Requirements', 'General', '20 U.S.C. § 1094; 20 U.S.C. § 1099c', NULL, 'Your institution must maintain specific financial standards to participate in federal Title IV student aid programs. You must demonstrate financial responsibility through composite score calculations and report significant financial events within 10 days to the Department of Education.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (129, 'higher-education-act-information-distributed-to-st', 'Higher Education Act: Information Distributed to Students', 'General', 'Public Law No. 110-315; 20 U.S.C. § 1092', NULL, 'Your Title IV-eligible postsecondary institution must annually distribute comprehensive disclosure information to students covering financial aid, institutional data, student outcomes, and campus security. You must provide seven distinct categories of information through direct distribution, website posting, or electronic means to ensure students can make informed educational decisions.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (130, 'higher-education-act-net-price-calculator', 'Higher Education Act: Net Price Calculator', 'General', '20 U.S.C. § 1015; 20 U.S.C. § 1015a', NULL, 'Your institution must maintain a prominent net price calculator on your primary website that enables students to estimate their individual cost of attendance using Department of Education templates. You must update calculator data annually with comprehensive cost information and financial aid amounts, and submit detailed explanatory reports if your institution appears on the Department''s high-cost increase list.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (131, 'higher-education-act-plus-loans', 'Higher Education Act: PLUS Loans', 'General', 'Public Law No. 110-315; 20 U.S.C. § 1078-2', NULL, 'Your institution must administer PLUS loans through the Federal Direct Loan Program, verifying borrower eligibility and credit history for parent and graduate student loans. You must maintain accurate cost of attendance calculations, process disbursements according to federal requirements, and provide required counseling to borrowers.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (159, 'fcc-fixed-microwave-services-licensing', 'FCC – Fixed Microwave Services, Licensing', 'Information Technology', '47 U.S.C. § 151', NULL, 'The University must file an application to provide fixed microwave services electronically via ULS for each Digital Electronic Message Service (DEMS) Nodal Station. Licensee may not be a foreign government or representative of a foreign government.
INSERT INTO public.regulations VALUES (132, 'higher-education-act-penalties-for-drug-violations', 'Higher Education Act: Penalties for Drug Violations', 'General', '20 U.S.C. 1092(k)', NULL, 'Your institution must notify all students about drug conviction penalties that result in immediate loss of federal financial aid eligibility. You must implement systematic procedures to identify affected students, provide required notifications about suspension periods, and maintain documentation for federal audit purposes.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (133, 'higher-education-act-perkins-loans', 'Higher Education Act: Perkins Loans', 'General', 'Public Law No. 110-315; 20 U.S.C. §§ 1087aa-1087ii', NULL, 'Your institution must manage the Federal Perkins Loan Program using only existing institutional funds and borrower collections, as federal appropriations ended after fiscal year 2015. You must provide loans exclusively to students with exceptional financial need while maintaining comprehensive borrower counseling and disclosure requirements.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (134, 'higher-education-act-preferred-lenders', 'Higher Education Act: Preferred Lenders', 'Financial Aid', 'Public Law No. 110-315; 20 U.S.C. § 1094(h)', NULL, 'The university may maintain a preferred vendor list so long as it is not used to deny or impede a borrower''s choice of lenders, offers three or more lenders not affiliated with one another, and doesn''t include lenders who have offered financial or other benefits to be included on the list.
INSERT INTO public.regulations VALUES (135, 'higher-education-act-record-retention', 'Higher Education Act: Record Retention', 'General', '34 CFR § 668.24', NULL, 'Your institution must maintain comprehensive records for all Title IV federal student aid programs and retain documentation for specified periods to ensure proper administration and accountability. You must document institutional eligibility, student financial aid records, disbursements, and compliance activities while preserving records for three years or until audit resolution.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (136, 'higher-education-act-standard-of-conduct', 'Higher Education Act: Standard of Conduct', 'General', 'Public Law No. 110-315', NULL, 'Your institution must administer federal student aid programs with the highest fiduciary standard of care and maintain strict accountability for all Title IV funds. You must implement comprehensive compliance systems, accurate recordkeeping, and robust internal controls to protect federal funding eligibility.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (137, 'student-loan-default-prevention-initiative-act-of-', 'Student Loan Default Prevention Initiative Act of 1990', 'General', '20 U.S.C. §§ 1001-1019d', NULL, 'Your institution must maintain federal student loan cohort default rates below 25% for three consecutive years or 40% in any single year to remain eligible for Title IV federal aid programs. You must implement comprehensive default prevention strategies, provide mandatory loan counseling, and submit detailed compliance reporting to avoid immediate suspension from Federal Direct Loan, FFEL, and Pell Grant programs.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (138, 'student-right-to-know-act', 'Student Right to Know Act', 'General', '20 U.S.C. § 1092; Public Law No. 101-542', NULL, 'Your postsecondary institution must provide comprehensive disclosure of financial aid information, academic programs, and completion rates to all prospective and enrolled students participating in federal student aid programs. You must maintain qualified financial aid staff, publish required information through multiple channels, and ensure students receive essential data to make informed educational decisions.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (144, 'internal-revenue-service-governance-information-re', 'Internal Revenue Service: Governance Information Required on Form 990', 'Governance', '26 U.S.C. § 6033; IRS Form 990 Instructions', NULL, 'The IRS asks 501(c)(3) organizations about their management and governance practices on the Form 990.', '', 'Ethics & Governance', 'federal', true, NULL, NULL, '2026-06-25 15:35:13.817654', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Internal Revenue Service mandates comprehensive governance disclosure requirements for tax-exempt organizations under Section 501(c)(3) of the Internal Revenue Code, codified at 26 U.S.C. § 501(c)(3), with implementing regulations found in 26 CFR § 1.501(c)(3)-1. Higher education institutions holding tax-exempt status must complete Form 990, which includes detailed governance information in Part VI, pursuant to Treasury Regulations § 1.6033-2(a)(2)(i). The regulation requires disclosure of governing body composition, including the number of voting members, independent members, and any material conflicts of interest policies. Universities must report whether they maintain a conflict of interest policy covering directors, trustees, officers, and key employees, as mandated by 26 CFR § 53.4958-6(c). Institutions must disclose their whistleblower policy compliance under Section 1107 of the Sarbanes-Oxley Act, codified at 18 U.S.C. § 1514A, which extends protections to nonprofit employees. Document retention and destruction policies must be reported, referencing compliance with 18 U.S.C. § 1519 obstruction of justice provisions. The regulation encompasses CEO/executive compensation determination processes, requiring disclosure of comparability data usage and independent review procedures under intermediate sanctions rules in 26 U.S.C. § 4958. Universities must report governing document amendments, joint venture policies, and any business relationships with interested persons. Form 990 Part VI specifically addresses whether the organization provided copies of Form 990 to governing body members before filing, ensuring transparency in governance oversight. Penalties for non-compliance include automatic revocation of tax-exempt status under 26 U.S.C. § 6033(j) for organizations failing to file for three consecutive years. The IRS may impose excise taxes on excess benefit transactions under Section 4958, with initial taxes of 25% on the disqualified person and 10% on organization managers. Recent amendments through the Tax Cuts and Jobs Act of 2017 expanded reporting requirements for executive compensation and added new excise taxes on compensation exceeding $1 million annually at exempt organizations under 26 U.S.C. § 4960. Higher education institutions face enhanced scrutiny due to their significant endowments and public trust responsibilities, making governance transparency particularly critical for maintaining tax-exempt status and public accountability.', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2026-06-25 15:35:13.817654', NULL, true, NULL, NULL, NULL, NULL, '', NULL, NULL, 'federal', NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', false, 'annual', NULL, NULL, NULL, NULL, NULL, NULL, 'REG-184', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.regulations VALUES (145, 'department-of-education-general-administrative-reg', 'Department of Education General Administrative Regulations and Other Applicable Grant Regulations', 'Grants Management', '2 CFR Part 200; 34 CFR Parts 75-79', NULL, 'The Department of Education''s General Administrative Regulations (EDGAR) regulate the administration of grants and agreements with certain programs, including direct grant programs, state administered programs, drug and alcohol abuse prevention programs, and research involving human subjects.
INSERT INTO public.regulations VALUES (146, 'false-claims-act', 'False Claims Act', 'False Claims Prohibition', '31 U.S.C. §§ 3729-3733', NULL, 'The False Claims Act prohibits knowingly submitting false claims to the federal government. It is primarily an enforcement statute, not a compliance statute with affirmative requirements. The main compliance obligation is protecting whistleblowers from retaliation under 31 USC 3730(h).', 'FALSE CLAIMS ACT REQUIREMENTS:
INSERT INTO public.regulations VALUES (147, 'federal-awardee-performance-and-integrity-informat', 'Federal Awardee Performance and Integrity Information System (FAPIIS)', 'Grants Management', 'Public Law No. 110-417, § 872; 41 U.S.C. § 2313', NULL, 'Federal Awardee Performance and Integrity Information System (FAPIIS) is a federally-mandated information system that contains specific information on the integrity and ethical performance of covered Federal contractors and grantees.', '', 'Research', 'federal', true, NULL, NULL, '2026-06-25 15:35:13.903543', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Federal Awardee Performance and Integrity Information System (FAPIIS) was established under Public Law No. 110-417, § 872, codified at 41 U.S.C. § 2313, as a comprehensive database designed to enhance federal oversight of contractors and grantees, including higher education institutions receiving federal awards. This system serves as a centralized repository for performance and integrity information that federal awarding agencies must review before making award decisions exceeding $500,000.
INSERT INTO public.regulations VALUES (148, 'federal-funding-accountability-and-transparency-ac', 'Federal Funding Accountability and Transparency Act of 2006 (FFATA)', 'Grants Management', 'Public Law No. 109-282; P.L. 110-252, § 6202', NULL, 'The Act requires full disclosure to public of all entities/orgs receiving federal funds via single searchable website accessible to public at no cost (www.USASpending.gov).
INSERT INTO public.regulations VALUES (149, 'fraud-enforcement-and-recovery-act-of-2009-fera', 'Fraud Enforcement and Recovery Act of 2009 (FERA)', 'Grants Management', 'Public Law No. 111-21', NULL, 'The Act clarifies that the False Claims Act was intended to cover to any false or fraudulent claim for government money or property, regardless of whether the claim is presented to a government official or employee, whether the government has physical custody of the money, or whether the defendant specifically intended to defraud the government.
INSERT INTO public.regulations VALUES (150, 'controlled-substances-act', 'Controlled Substances Act', 'Health Care and Insurance', '21 U.S.C. §§ 801-889', NULL, 'Regulates the manufacture and distribution of narcotics, stimulants, depressants, hallucinogens, anabolic steroids, and chemicals used in the illicit production of controlled substances.
INSERT INTO public.regulations VALUES (160, 'fcc-wireless-communications-licensing', 'FCC – Wireless Communications, Licensing', 'Information Technology', '47 U.S.C. § 151', NULL, 'The University''s authorization to provide wireless communication services is granted for any or a combination of the following services in a single license: 1) common carrier; 2) non-common carrier; 3) private internal communications; 4) and broadcast services.
INSERT INTO public.regulations VALUES (151, 'hipaa', 'Health Insurance Portability and Accountability Act (HIPAA)', 'Health Information Privacy', 'Public Law 104-191; 45 CFR Parts 160, 162, 164', NULL, 'HIPAA establishes national standards for protecting sensitive patient health information. For higher education institutions with student health services, counseling centers, or health-related programs, HIPAA requires implementing administrative, physical, and technical safeguards to ensure confidentiality, integrity, and availability of protected health information (PHI). Key compliance areas include the Privacy Rule, Security Rule, Breach Notification Rule, and Business Associate requirements.', 'HIPAA COMPLIANCE REQUIREMENTS:
INSERT INTO public.regulations VALUES (152, 'higher-education-opportunity-act', 'Higher Education Opportunity Act', 'Information Technology', 'Public Law No. 110-315', NULL, 'Section 488 requires institutions to develop plans to detect and prevent unauthorized distribution of copyrighted material on information technology systems, including offering alternatives to illegal-downloading or peer-to-peer distribution of intellectual property.', '', 'Information Technology', 'federal', true, NULL, NULL, '2026-06-25 15:35:14.04604', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, '**REGULATORY COMPLIANCE REFERENCE: HIGHER EDUCATION OPPORTUNITY ACT SECTION 488 - PEER-TO-PEER FILE SHARING PREVENTION**
INSERT INTO public.regulations VALUES (153, 'nsf-grant-term-and-condition-september-21-2018', 'NSF grant term and condition, September 21, 2018', 'Human Resources', 'NSF Proposal & Award Policies and Procedures Guide', NULL, 'National Science Foundation new term and condition requires recipients of NSF awards to notify NSF of any findings/determinations of sexual harassment, other forms of harassment, of sexual assault regarding an NSF-funded PI or co-PI.', '', 'Human Resources', 'federal', true, NULL, NULL, '2026-06-25 15:35:14.074006', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The National Science Foundation (NSF) Sexual Harassment Reporting Term and Condition, effective September 21, 2018, represents a significant expansion of federal oversight regarding misconduct in federally-funded research. This regulation operates under NSF''s authority pursuant to the National Science Foundation Act of 1950, as amended (42 U.S.C. § 1862 et seq.), and the Federal Grant and Cooperative Agreement Act (31 U.S.C. § 6301 et seq.).
INSERT INTO public.regulations VALUES (154, 'student-exchange-and-visitor-information-system-se', 'Student Exchange and Visitor Information System (SEVIS)', 'Immigration', '8 U.S.C. § 1372; 8 CFR Part 214', NULL, 'The Student and Exchange Visitor Program (SEVP) acts as the bridge for various government organizations that have an interest in information on foreign students.
INSERT INTO public.regulations VALUES (155, 'immigration-and-nationality-act-ina', 'Immigration and Nationality Act (INA)', 'Immigration,Recruitment Hiring & Termination', '8 U.S.C. §§ 1101-1537', NULL, 'The INA, as amended, sets forth the laws governing the admission and employment of foreign nationals in the United States, including provisions that address employment eligibility and employment verification.', '', 'Human Resources', 'federal', true, NULL, NULL, '2026-06-25 15:35:14.132244', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Immigration and Nationality Act (INA), codified at 8 U.S.C. §§ 1101-1537, establishes the comprehensive legal framework governing foreign national admission, employment, and verification in the United States. For higher education institutions, the INA''s employment eligibility verification provisions under 8 U.S.C. § 1324a are particularly critical, requiring verification of all employees'' work authorization through Form I-9 completion within three business days of hire.
INSERT INTO public.regulations VALUES (156, 'communications-assistance-for-law-enforcement-act-', 'Communications Assistance for Law Enforcement Act (CALEA)', 'Information Technology', '47 U.S.C. §§ 1001-1010', NULL, 'CALEA requires a "telecommunications carrier," as defined by the Act, to ensure that equipment, facilities, or services that allow a customer or subscriber to "originate, terminate, or direct communications," enable law enforcement officials to conduct electronic surveillance pursuant to court order or other lawful authorization.', '', 'Information Technology', 'federal', true, NULL, NULL, '2026-06-25 15:35:14.227729', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Communications Assistance for Law Enforcement Act (CALEA), codified at 47 U.S.C. §§ 1001-1010, mandates that telecommunications carriers and certain broadband internet access service providers enable law enforcement agencies to conduct lawful electronic surveillance. The Federal Communications Commission (FCC) has expanded CALEA''s scope through rulings under 47 CFR Part 64, Subpart AA, requiring compliance from facilities-based broadband internet access service providers and Voice over Internet Protocol (VoIP) service providers.
INSERT INTO public.regulations VALUES (157, 'electronic-communications-privacy-act-of-1986', 'Electronic Communications Privacy Act of 1986', 'Information Technology', '18 U.S.C. §§ 2510-2523 (Wiretap); 18 U.S.C. §§ 2701-2713 (Stored Communications)', NULL, 'The ECPA, as amended, protects wire, oral, and electronic communications while those communications are being made, are in transit, and when they are stored on computers.
INSERT INTO public.regulations VALUES (158, 'fcc-cable-certification', 'FCC – Cable Certification', 'Information Technology', '47 U.S.C. § 151', NULL, 'Prior to commencing service, cable television systems, cable operators, and satellite carriers must obtain certification that they are in conformity with signal carriage, program exclusivity, cable casting, and other standards.
INSERT INTO public.regulations VALUES (161, 'homeland-security-act-of-2002', 'Homeland Security Act of 2002', 'General', '6 U.S.C. §§ 101 – 674', NULL, 'Your institution must implement comprehensive cybersecurity frameworks and coordinate with the Department of Homeland Security to protect critical infrastructure and federal information systems. You must establish incident response protocols, conduct regular security assessments, and report significant cybersecurity incidents to DHS within 72 hours.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (162, 'junk-fax-prevention-act-of-2005', 'Junk Fax Prevention Act of 2005', 'Information Technology', 'Public Law 109–21', NULL, 'Applicable to non-profits, the Act provides that it is unlawful for the University to use a fax machine to send an unsolicited advertisement to another fax machine unless there is: 1) An established business relationship; 2) the sender obtained the fax number through voluntary communication with the recipient; and 3) the first page of the fax conspicuously states the recipient can request no further unsolicited communications.
INSERT INTO public.regulations VALUES (163, 'no-electronic-theft-act', 'No Electronic Theft Act', 'Information Technology', 'No Electronic Theft (NET) Act', NULL, 'Makes it a criminal offense to willfully infringe a copyright by sharing, as well as selling, pirated software with a retail value of $1,000 or more.
INSERT INTO public.regulations VALUES (164, 'telemarketing', 'Telemarketing', 'Information Technology', '47 U.S.C. § 227', NULL, 'A tax-exempt nonprofit University is exempt from the Do-Not-Call-Registry, but may not call any residential telephone subscriber before 8 a.m. or after 9 p.m. local time at the called party''s location.', '', 'Information Technology', 'federal', true, NULL, NULL, '2026-06-25 15:35:14.456344', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Telephone Consumer Protection Act (TCPA), codified at 47 U.S.C. § 227, establishes comprehensive federal regulations governing telemarketing practices, with specific provisions affecting higher education institutions. Under 47 CFR § 64.1200(c)(2), tax-exempt nonprofit organizations, including accredited universities and colleges, are exempt from the National Do Not Call Registry requirements established by the Federal Trade Commission. This exemption permits universities to contact individuals for legitimate educational purposes, including recruitment, fundraising, alumni relations, and academic program promotion, without first checking the Do Not Call Registry.
INSERT INTO public.regulations VALUES (165, 'american-jobs-creation-act-of-2004', 'American Jobs Creation Act of 2004', 'Intellectual Property and Technology Transfer', '26 U.S.C. § 170', NULL, 'For contributions of patents and certain other intellectual property made to a 501(c)(3) after June 3, 2004 the taxpayer''s initial contribution deduction is limited to the lesser of the donor''s basis in the contributed property or the fair market value of the property.', '', 'Intellectual Property', 'federal', true, NULL, NULL, '2026-06-25 15:35:14.484796', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The American Jobs Creation Act of 2004 significantly modified the federal tax treatment of intellectual property donations to tax-exempt organizations, including higher education institutions. Under 26 U.S.C. § 170(e)(1)(B)(iii), the Act fundamentally altered charitable deduction calculations for patents, copyrights, trademarks, trade names, trade secrets, know-how, software, and similar intellectual property donated to 501(c)(3) organizations after June 3, 2004.
INSERT INTO public.regulations VALUES (166, 'bayh-dole-act-of-1980', 'Bayh-Dole Act of 1980', 'Intellectual Property and Technology Transfer', '35 U.S.C. §§ 200-212', NULL, 'Establishes a uniform policy for the disposition and licensing of rights to patentable inventions discovered in the course of federally-funded research.', '', 'Intellectual Property', 'federal', true, NULL, NULL, '2026-06-25 15:35:14.517117', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Bayh-Dole Act of 1980, codified at 35 U.S.C. §§ 200-212, revolutionized federal technology transfer policy by allowing universities, small businesses, and nonprofit organizations to retain title to inventions developed with federal funding. This landmark legislation, implemented through 37 C.F.R. Part 401, fundamentally shifted from government ownership to institutional ownership of federally-funded innovations.
INSERT INTO public.regulations VALUES (167, 'cooperative-research-and-technology-enhancement-ac', 'Cooperative Research and Technology Enhancement Act (CREATE Act)', 'General', 'Public Law No. 108-453', NULL, 'Your university must establish formal joint research agreements and maintain comprehensive documentation to protect patent rights under collaborative research arrangements. You must ensure all research partnerships are properly structured in writing before invention dates to prevent prior art challenges that could invalidate your patents.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (168, 'trademark-revision-act', 'Trademark Revision Act', 'Intellectual Property and Technology Transfer', '15 U.S.C. § 1051; Public Law No. 109-312', NULL, 'Subject to the principles of equity, the owner of a famous mark that is distinctive, inherently or through acquired distinctiveness, shall be entitled to an injunction against another person who, at any time after the owner''s mark has become famous, commences use of a mark or trade name in commerce that is likely to cause dilution by blurring or dilution by tarnishment of the famous mark, regardless of the presence or absence of actual or likely confusion, of  competition, or of actual economic injury.', '', 'Intellectual Property', 'federal', true, NULL, NULL, '2026-06-25 15:35:14.573097', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Trademark Revision Act, codified at 15 U.S.C. § 1051 and enacted through Public Law No. 109-312, establishes federal protections against trademark dilution for famous marks, with significant implications for higher education institutions managing extensive intellectual property portfolios. This legislation expands beyond traditional trademark infringement by protecting famous marks from dilution by blurring or tarnishment, regardless of consumer confusion or direct competition.
INSERT INTO public.regulations VALUES (169, 'u-s-patent-act', 'U.S. Patent Act', 'Intellectual Property and Technology Transfer', '35 U.S.C. §§ 1-390', NULL, 'The consolidated patent laws specify the subject matter for which a patent may be obtained and the conditions for patentability.  They also include requirements related to representation before the U.S. Patent and Trademark Office, applications for registration, examination procedures, amendment of applications, publication and post publication procedures, appeals, petitions, post registration practice, correspondence in trademark cases, classification of goods and services, and procedures under the Madrid Protocol.
INSERT INTO public.regulations VALUES (170, 'visual-artists-rights-act', 'Visual Artists Rights Act', 'Intellectual Property and Technology Transfer', '17 U.S.C. § 106A', NULL, 'Protects moral rights for fine art works, but does not protect audiovisual works and probably does not apply to most multimedia creations.', '', 'Intellectual Property', 'federal', true, NULL, NULL, '2026-06-25 15:35:14.628726', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Visual Artists Rights Act (VARA), codified at 17 U.S.C. § 106A, establishes moral rights for authors of works of visual art, granting artists specific rights of attribution and integrity that survive economic transfers of ownership. Enacted in 1990 as part of the Copyright Act amendments, VARA provides qualifying visual artists with the right to claim authorship of their work and prevent uses that would prejudice their honor or reputation.
INSERT INTO public.regulations VALUES (171, 'foreign-agents-registration-act-of-1938', 'Foreign Agents Registration Act of 1938', 'International Activities and Programs', '22 U.S.C. §§§ 611-621', NULL, 'Requires persons acting as agents of foreign principals in a political or quasi-political capacity to make periodic public disclosure of their relationship with the foreign principal, as well as activities, receipts and disbursements in support of those activities.
INSERT INTO public.regulations VALUES (172, 'foreign-corrupt-practices-act-fcpa', 'Foreign Corrupt Practices Act (FCPA)', 'International Activities and Programs', '15 U.S.C. §§ 78dd-1, et seq.', NULL, 'Makes it unlawful for certain classes of persons and entities to make payments to foreign government officials to assist in obtaining or retaining business.
INSERT INTO public.regulations VALUES (173, 'honest-leadership-and-open-government-act-of-2007', 'Honest Leadership and Open Government Act of 2007', 'Lobbying and Political Activities', 'Pub. L. 110-81; 2 U.S.C. § 1601 et seq.', NULL, 'Made a number of changes to the Lobbying Disclosure Act, including a ban on most gifts from an independent college or university that employs or engages a lobbyist.', '', 'Ethics & Governance', 'federal', true, NULL, NULL, '2026-06-25 15:35:14.778651', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Honest Leadership and Open Government Act of 2007 (HLOGA), codified at 2 U.S.C. §§ 1601-1614, significantly amended the Lobbying Disclosure Act of 1995 (LDA) to enhance transparency and accountability in lobbying activities. For higher education institutions, HLOGA imposes critical restrictions on gift-giving and lobbying practices that directly impact institutional operations and federal relationships.
INSERT INTO public.regulations VALUES (174, 'lobbying-disclosure-act', 'Lobbying Disclosure Act', 'Lobbying and Political Activities', '2 U.S.C. §§ 1601-1614; Public Law No. 104-65, 109 Stat. 691', NULL, 'Requires institutions to register if they employ (as a salaried employee) individuals who make at least two lobbying contacts each six months and devote 20% of their time to lobbying activities and incur expenses for lobbying of $20,000 or more in a six-month period.
INSERT INTO public.regulations VALUES (175, 'political-activities', 'Political Activities', 'Lobbying and Political Activities', 'IRC § 501 (c )(3)', NULL, 'All section 501(c)(3) organizations are absolutely prohibited from directly or indirectly participating in, or intervening in, any political campaign on behalf of (or in opposition to) any candidate for elective public office.
INSERT INTO public.regulations VALUES (176, 'children-s-online-privacy-protection-act-of-1998-c', 'Children’s Online Privacy Protection Act of 1998 (COPPA)', 'General', '15 U.S.C. §  6501', NULL, 'Your organization must protect children under 13 when operating websites or online services that target minors or knowingly collect their personal information. You must obtain verifiable parental consent before collecting data, post clear privacy notices, and implement security measures to protect collected information.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (177, 'electronic-communications-privacy-act', 'Electronic Communications Privacy Act', 'General', '18 U.S.C. §§ 2510-2523 (Wiretap); 18 U.S.C. §§ 2701-2713 (Stored Communications)', NULL, 'Your organization must protect electronic communications from unauthorized interception and access under federal privacy laws. You must establish clear policies for email monitoring, network surveillance, and law enforcement cooperation while ensuring proper legal authorization for any communication access.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (178, 'fair-and-accurate-credit-transaction-act-facta', 'Fair and Accurate Credit Transaction Act (FACTA)', 'Privacy & Information Security', 'Public Law No. 108-159', NULL, 'Amends the Fair Credit Reporting Act
INSERT INTO public.regulations VALUES (192, 'federal-volunteer-protection-act', 'Federal Volunteer Protection Act', 'Recruitment Hiring & Termination', 'Public Law No. 105-19; 42 U.S.C. §§ 14501-14505', NULL, 'Partially protects individual volunteers for non-profit organizations and governmental entities from liability for acts of negligence in the course of their volunteer work.', '', 'Human Resources', 'federal', true, NULL, NULL, '2026-06-25 15:35:15.389175', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Federal Volunteer Protection Act of 1997, codified at 42 U.S.C. §§ 14501-14505, provides qualified liability protection for volunteers serving nonprofit organizations and governmental entities, including public higher education institutions. This federal legislation establishes uniform standards across states to encourage volunteer service by limiting personal liability exposure for good-faith volunteer activities.
INSERT INTO public.regulations VALUES (179, 'family-educational-rights-and-privacy-act-ferpa', 'Family Educational Rights and Privacy Act (FERPA)', 'General', '20 U.S.C. § 1232', NULL, 'The University must provide students the right to inspect their education records and obtain written consent to release the records to anyone other than school officials, authorized government personnel, in connection with financial aid, in an emergency, or for other specifically-allowed purposes.', 'FERPA COMPLIANCE REQUIREMENTS (34 CFR Part 99)
INSERT INTO public.regulations VALUES (180, 'federal-information-security-management-act-fisma', 'Federal Information Security Management Act (FISMA)', 'General', '44 U.S.C. § 35', NULL, 'Your university must implement comprehensive information security programs when handling federal data or managing federally-funded research systems. You must conduct risk assessments, categorize information systems, and maintain continuous monitoring with documented security controls that meet NIST standards.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (181, 'freedom-of-information-act', 'Freedom of Information Act', 'General', '5 U.S.C. § 552', NULL, 'Your public institution must provide access to federal agency records and respond to information requests within statutory timeframes. You must establish processing procedures, designate FOIA officers, and balance disclosure obligations with student privacy protections under FERPA.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (182, 'gramm-leach-bliley-act-glba', 'Gramm Leach Bliley Act (GLBA)', 'General', '15 U.S.C. § 6801', NULL, 'Your financial institution must protect nonpublic personal information of customers and provide annual privacy notices explaining data collection and sharing practices. You must implement comprehensive information security programs with written safeguards, conduct regular risk assessments, and provide customers opt-out rights for non-essential information sharing.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (183, 'health-information-technology-for-economic-and-cli', 'Health Information Technology for Economic and Clinical Health (HITECH) Act of 2009', 'General', 'Public Law No. 111-5', NULL, 'Your organization must strengthen HIPAA privacy and security protections for protected health information under HITECH Act requirements. You must implement enhanced safeguards, ensure business associate compliance, and establish mandatory breach notification procedures with substantial penalties for violations.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (193, 'worker-adjustment-and-retraining-notification-act-', 'Worker Adjustment and Retraining Notification Act (WARN)', 'Recruitment Hiring & Termination', '29 U.S.C. § 2101 et seq. (WARN Act)', NULL, 'The University must provide 60 days advance notice of plant closings or mass layoffs to affected workers (whether hourly or salaried, including managers or supervisors) or their representatives (i.e. labor union).
INSERT INTO public.regulations VALUES (194, 'america-competes-act', 'America COMPETES Act', 'Research', 'Public Law No. 111-358; 42 U.S.C. § 1862o-1', NULL, 'Requires that each institution that applies for financial assistance from the National Science Foundation for science and engineering research or education describe in its grant proposal a plan to provide appropriate training and oversight in the responsible and ethical conduct of research to undergraduate students, graduate students, and postdoctoral researchers participating in the proposed research project.', '', 'Research', 'federal', true, NULL, NULL, '2026-06-25 15:35:15.445675', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The America Creating Opportunities to Meaningfully Promote Excellence in Technology, Education, and Science (COMPETES) Act of 2010, codified at 42 U.S.C. § 1862o-1, establishes mandatory research integrity training requirements for higher education institutions receiving National Science Foundation (NSF) funding. This federal regulation fundamentally transformed research compliance obligations by requiring comprehensive responsible conduct of research (RCR) training programs.
INSERT INTO public.regulations VALUES (184, 'higher-education-act-financial-value-transparency-', 'Higher Education Act Financial Value Transparency & Gainful Employment', 'Program Integrity Rules', '20 U.S.C. §§ 1001, 1002', NULL, 'To be Title IV eligible, an educational program must either lead to a degree awarded by a public or nonprofit institution or prepare students for gainful employment (GE) in a recognized occupation.  Thus, GE programs are non-degree programs at public and nonprofit institutions, and essentially all programs at proprietary institutions.', '', 'Financial Aid', 'federal', true, NULL, NULL, '2026-06-25 15:35:15.095113', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Higher Education Act Financial Value Transparency and Gainful Employment regulations, codified under 20 U.S.C. §�� 1001-1002 and implemented through 34 CFR § 668.6, establish fundamental eligibility requirements for Title IV federal student aid programs. These regulations mandate that educational programs must either lead to a degree from public or nonprofit institutions or prepare students for gainful employment in recognized occupations.
INSERT INTO public.regulations VALUES (185, 'higher-education-act-credit-hour-definition', 'Higher Education Act: Credit Hour Definition', 'Program Integrity Rules', '20 U.S.C. §§ 1001, 1002', NULL, 'Provides a federal definition of credit hour.', '', 'Financial Aid', 'federal', true, NULL, NULL, '2026-06-25 15:35:15.123715', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Higher Education Act Credit Hour Definition regulation, codified under 34 CFR § 600.2, establishes the federal definition of credit hour for all Title IV eligible institutions participating in federal student aid programs. This regulation serves as a cornerstone of program integrity rules, ensuring consistency in academic standards and protecting federal investment in higher education.
INSERT INTO public.regulations VALUES (186, 'higher-education-act-incentive-compensation-prohib', 'Higher Education Act: Incentive Compensation Prohibition', 'Program Integrity Rules', '20 U.S.C. § 1094', NULL, 'Institutions are prohibited from providing any commission, bonus, or other incentive payment based in any part, directly or indirectly, upon success in securing enrollments or the award of financial aid, to any person or entity who is engaged in any student recruitment or admission activity, or in making decisions regarding the award of Title IV, HEA program funds.
INSERT INTO public.regulations VALUES (187, 'higher-education-act-misrepresentation', 'Higher Education Act: Misrepresentation', 'Program Integrity Rules', '20 U.S.C. § 1094', NULL, 'Makes the institution responsible for substantial misrepresentations made by the institution itself, a representative of the institution, or any person or entity with whom the institution has an agreement to provide educational programs, marketing, advertising, and recruiting or admissions services.
INSERT INTO public.regulations VALUES (188, 'higher-education-act-state-authorization', 'Higher Education Act: State Authorization', 'Program Integrity Rules', '20 U.S.C. §§ 1001, 1002', NULL, 'In order for its students to be eligible for Title IV student financial assistance, an institution must be able to demonstrate to ED that it meets the legal authorization standards of every state in which it operates.
INSERT INTO public.regulations VALUES (189, 'drug-alcohol-testing-of-transportation-employees', 'Drug & Alcohol Testing of Transportation Employees', 'Recruitment Hiring & Termination', '49 U.S.C. § 31144', NULL, 'Commercial motor vehicle operators are subject to pre-employment drug testing, and post-accident, random and reasonable suspicion drug and alcohol testing.  Testing is mandatory if the driver is involved in a fatal accident.
INSERT INTO public.regulations VALUES (190, 'drug-free-workplace-act', 'Drug Free Workplace Act', 'Recruitment Hiring & Termination', '41 U.S.C. §§ 701-707', NULL, 'A federal contractor receiving $25,000 or more in funding must: 1) Certify it provides a drug-free workplace; 2) publish a statement notifying employees that unlawful manufacture, distribution, dispensing, possession, use of controlled substances is prohibited and stating what action will be taken for violations; 3) establish an ongoing drug-free awareness program; 4) require that each employee directly involved in the contract/grant work notify the employer of any criminal drug statute convictions for a violation occurring in the workplace (however, drug testing is not mandated or authorized); 5) notify the federal government of such a violation within ten days after learning of conviction; and 6) require sanctions or remedial measures for an employee convicted of a drug abuse violation in the workplace.
INSERT INTO public.regulations VALUES (191, 'employee-polygraph-protection-act', 'Employee Polygraph Protection Act', 'Recruitment Hiring & Termination', '29 U.S.C. §§ 2001-2009', NULL, 'The University may not:
INSERT INTO public.regulations VALUES (195, 'animal-welfare-act', 'Animal Welfare Act', 'Research', '7 U.S.C. §§ 2131-2159', NULL, 'Governs the treatment of animals used for research: dogs, cats, monkeys, guinea pigs, hamsters, and other warm-blooded animals.', '', 'Research', 'federal', true, NULL, NULL, '2026-06-25 15:35:15.474003', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Animal Welfare Act (AWA), codified at 7 U.S.C. §§ 2131-2159, establishes federal standards for the treatment of animals used in research, exhibition, transport, and by dealers. For higher education institutions, this regulation is critical as many universities conduct research involving covered animals including dogs, cats, non-human primates, guinea pigs, hamsters, rabbits, and other warm-blooded animals except birds, rats, and mice bred for research.
INSERT INTO public.regulations VALUES (196, 'clinical-trials-financial-disclosures-by-investiga', 'Clinical Trials § Financial Disclosures by Investigator', 'Research', '42 CFR Part 50, Subpart F', NULL, 'Clinical investigators are required to disclose financial arrangements with sponsor(s) of the studies (such as payment and royalties) and interests in the product under study or sponsor entity (i.e. proprietary interest such as a patent or other equity interest).', '', 'Research', 'federal', true, NULL, NULL, '2026-06-25 15:35:15.50307', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Clinical Trials Financial Disclosures by Investigator regulation, codified under 21 CFR Part 54, establishes mandatory disclosure requirements for clinical investigators conducting FDA-regulated studies. This regulation operates under the authority of the Federal Food, Drug, and Cosmetic Act (21 U.S.C. § 355) and applies comprehensively to higher education institutions conducting clinical research.
INSERT INTO public.regulations VALUES (197, 'export-administration-regulations', 'Export Administration Regulations', 'General', '15 CFR Parts 730-774 (EAR)', NULL, 'Your institution must control the export of dual-use goods, technology, and software that have both civilian and military applications. You must obtain proper licenses before exporting controlled items, screen international collaborators against denied persons lists, and carefully structure research agreements to maintain fundamental research exclusions.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (198, 'food-and-drug-administration-fda-amendments-act-of', 'Food and Drug Administration (FDA) Amendments Act of 2007', 'Research', 'Public Law No. 110-85', NULL, 'For an investigational new drug to be used in a clinical investigation, the University must ensure the sponsor submits an Investigational New Drug Application and complies with all applicable requirements with respect to the regulations pertaining to human subjects and IRB review and approval.
INSERT INTO public.regulations VALUES (199, 'national-science-foundation-research-misconduct-po', 'National Science Foundation Research Misconduct Policies', 'General', '42 U.S.C. § 1870(a)', NULL, 'A finding of research misconduct requires that: (1) there be a significant departure from accepted practices of the relevant research community; (2) the research misconduct be committed intentionally, or knowingly, or recklessly; and (3) the allegation be proven by a preponderance of evidence.', '', 'Research', 'federal', true, NULL, NULL, '2026-06-25 15:35:15.58899', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The National Science Foundation Research Misconduct Policies, codified under 42 U.S.C. § 1870(a) and implemented through 45 CFR Part 689, establish comprehensive standards for investigating and adjudicating research misconduct allegations at institutions receiving NSF funding. These regulations define research misconduct as fabrication, falsification, or plagiarism in proposing, performing, or reviewing research, or in reporting research results, with three critical elements required for a finding: (1) significant departure from accepted practices of the relevant research community, (2) intentional, knowing, or reckless commission of the misconduct, and (3) proof by preponderance of evidence standard under 45 CFR § 689.3.
INSERT INTO public.regulations VALUES (200, 'native-american-graves-protection-and-repatriation', 'Native American Graves Protection and Repatriation Act (NAGPRA)', 'Research', '25 U.S.C. 32', NULL, '<li style="list-style-type: none;">
INSERT INTO public.regulations VALUES (201, 'protection-of-human-subjects-regulations-common-ru', 'Protection of Human Subjects Regulations (Common Rule)', 'Research', '45 CFR Part 46 (Common Rule)', NULL, 'Institutions must provide a written assurance application that they will comply with the Common Rule requirements. These requirements include written procedures for reporting to the institutional review board (IRB), institutional officials, and the department or agency head of unanticipated problems involving risks to subjects or serious or continuing non-compliance, and any suspension or termination of research.
INSERT INTO public.regulations VALUES (208, 'qualified-pensions', 'Qualified Pensions', 'Tax', '26 U.S.C. § 401', NULL, 'A trust created or organized in the United States and forming part of a stock bonus, pension, or profit-sharing plan of an employer for the exclusive benefit of his employees or their beneficiaries shall constitute a qualified trust.', '', 'Finance', 'federal', true, NULL, NULL, '2026-06-25 15:35:15.915211', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'Qualified pension plans under 26 U.S.C. § 401 represent employer-sponsored retirement benefit programs that must meet stringent federal tax qualification requirements to receive favorable tax treatment. For higher education institutions, these plans serve as critical components of faculty and staff compensation packages, providing systematically determined retirement benefits based on service years and compensation history rather than institutional profits.
INSERT INTO public.regulations VALUES (202, 'public-health-service-policies-on-research-miscond', 'Public Health Service Policies on Research Misconduct', 'General', '42 U.S.C. § 241', NULL, 'Your institution must establish comprehensive policies and procedures to prevent, detect, and respond to research misconduct in federally-funded biomedical and behavioral research. You must appoint a Research Integrity Officer, conduct timely investigations of misconduct allegations, and maintain strict documentation and reporting requirements to avoid suspension or termination of federal funding.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (203, 'responsibility-of-applicants-for-promoting-objecti', 'Responsibility of Applicants for Promoting Objectivity in Research for which PHS Funding is Sought', 'General', '42 CFR Part 50, Subpart F', NULL, 'Your institution must establish comprehensive financial conflict of interest policies for all researchers receiving Public Health Service funding exceeding $5,000. You must identify, manage, and report financial conflicts before research begins and maintain ongoing disclosure and training requirements for all investigators.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (204, 'small-unmanned-aircraft-systems', 'Small Unmanned Aircraft Systems', 'Research', '14 CFR Part 107 (FAA UAS)', NULL, 'Institutions are permitted to use small unmanned aircraft systems (UAS) in the National Airspace System for purposes that include research and development and educational/academic uses, provided that the institution follows operation and certification requirements.
INSERT INTO public.regulations VALUES (205, 'deferred-compensation', 'Deferred Compensation', 'Tax', '26 U.S.C. § 409A; 26 CFR § 1.409A', NULL, 'Any amount of compensation deferred under an eligible deferred compensation plan, and any income attributable to the amounts so deferred, shall be includible in gross income only for the taxable year in which such compensation or other income.', '', 'Finance', 'federal', true, NULL, NULL, '2026-06-25 15:35:15.830366', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'Section 457 of the Internal Revenue Code (26 U.S.C. § 457) governs eligible deferred compensation plans for state and local government employees, including public higher education institutions. This regulation establishes the tax treatment framework for compensation deferred under qualifying plans, stipulating that deferred amounts and attributable income are includible in gross income only when distributed to participants.
INSERT INTO public.regulations VALUES (206, 'employee-annuities', 'Employee Annuities', 'Tax', '26 U.S.C. § 403', NULL, 'If an annuity contract is purchased by an employer for an employee under a plan which meets the requirements of section 404(a)(2) (whether or not the employer deducts the amounts paid for the contract under such section), the amount actually distributed to any distributee under the contract shall be taxable to the distributee (in the year in which so distributed) under section 72 (relating to annuities).', '', 'Finance', 'federal', true, NULL, NULL, '2026-06-25 15:35:15.859053', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'Employee annuities under Section 403(a) of the Internal Revenue Code (26 U.S.C. § 403) establish critical tax treatment rules for retirement distributions at higher education institutions. This regulation governs tax-sheltered annuity plans, commonly known as 403(b) plans, which are exclusively available to employees of public schools, colleges, universities, and certain tax-exempt organizations under Section 501(c)(3).
INSERT INTO public.regulations VALUES (207, 'nonqualified-deferred-inclusion', 'Nonqualified Deferred Inclusion', 'Tax', '26 U.S.C. § 409A', NULL, 'If at any time during a taxable year a nonqualified deferred compensation plan I) fails to meet the requirements of paragraphs (2), (3), and (4), or (II) is not operated in accordance with such requirements, all compensation deferred under the plan for the taxable year and all preceding taxable years shall be includible in gross income for the taxable year to the extent not subject to a substantial risk of forfeiture and not previously included in gross income.', '', 'Finance', 'federal', true, NULL, NULL, '2026-06-25 15:35:15.886859', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'Section 409A of the Internal Revenue Code (26 U.S.C. § 409A) establishes comprehensive regulations governing nonqualified deferred compensation plans, with significant implications for higher education institutions offering supplemental retirement benefits to faculty and administrators. This provision, enacted as part of the American Jobs Creation Act of 2004, requires strict adherence to distribution timing, acceleration prohibitions, and election requirements to avoid severe tax penalties.
INSERT INTO public.regulations VALUES (209, 'cafeteria-plans-26-u-s-c-125', 'Cafeteria Plans 26 U.S.C. § 125', 'Tax', '26 U.S.C. § 125; 26 CFR § 1.125', NULL, 'A cafeteria plan is a written plan that allows employees to exclude from gross income certain types of employer provided benefits, such as accident and health insurance, group term and life insurance, and benefits under a dependent care assistance program.
INSERT INTO public.regulations VALUES (210, 'charitable-gift-annuity-antitrust-relief-act', 'Charitable Gift Annuity Antitrust Relief Act', 'Tax', '15 U.S.C. § 37; IRC § 501(c)(3)', NULL, 'Exempts IRC § 501(c)(3) organizations from liability under federal antitrust laws for using or agreeing to use uniform rates in issuing gift annuities.', '', 'Finance', 'federal', true, NULL, NULL, '2026-06-25 15:35:15.97207', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Charitable Gift Annuity Antitrust Relief Act, codified at 15 U.S.C. § 37, provides critical antitrust exemptions for tax-exempt organizations under IRC § 501(c)(3) engaging in charitable gift annuity programs. This federal legislation addresses the intersection of antitrust law and charitable fundraising by permitting qualified organizations to coordinate on annuity rates without violating the Sherman Act (15 U.S.C. §§ 1-7) or other federal antitrust statutes.
INSERT INTO public.regulations VALUES (211, 'federal-unemployment-tax-act', 'Federal Unemployment Tax Act', 'Wages', '26 U.S.C. §§ 3301-3311', NULL, 'Provides for payments of unemployment compensation to workers who have lost their jobs.
INSERT INTO public.regulations VALUES (212, 'foreign-bank-accounts-and-tax-filings', 'Foreign Bank Accounts and Tax Filings', 'Tax', '31 U.S.C. § 5314(a)', NULL, 'US institutions and citizens that have an ownership interest in foreign bank accounts, or US citizens with signature authority over a foreign bank account have to file form TD F 90.22-1 (FBAR).
INSERT INTO public.regulations VALUES (213, 'fringe-benefits', 'Fringe Benefits', 'Tax', '26 U.S.C. § 132', NULL, 'Any property or service (or cash under certain circumstances) provided to an employee in addition to or in lieu of regular wages will be a taxable fringe benefit to the employee, unless specifically excluded by statute.
INSERT INTO public.regulations VALUES (214, 'independent-contractors', 'Independent Contractors', 'Tax', '26 U.S.C. § 3121; IRS Rev. Rul. 87-41', NULL, 'If an employee is mistakenly classified as an independent contractor and the employer has no reasonable basis for doing so, the employer may be held liable for employment taxes for that worker.
INSERT INTO public.regulations VALUES (215, 'industrial-alcohol-user-permits-and-special-tax', 'Industrial Alcohol User Permits and Special Tax', 'Tax', '26 U.S.C. §§ 5001-5692', NULL, 'Institutions that procure, use, sell, and/or recover denatured distilled spirits for industrial purposes are required to obtain a permit from the ATF and pay an occupational tax of $250 per year.
INSERT INTO public.regulations VALUES (216, 'public-disclosure-of-material', 'Public Disclosure of Material', 'Tax', '26 U.S.C. § 6104(d)', NULL, 'The documents that must be made available to the public are: copies of the application for tax exemption (for those organizations which filed before July 15, 1987, this requirement only applies if the organization has a copy of the application on July 15, 1987); and copies of the organization''s three most recent annual information returns.
INSERT INTO public.regulations VALUES (217, 'reporting-of-payments-of-royalties', 'Reporting of Payments of Royalties', 'Tax', '20 U.S.C. § 6041; 26 U.S.C. § 6050N', NULL, 'Those who make payments to attorneys aggregating $600 or more per calendar year in connection with legal services must file an information return for such payments.
INSERT INTO public.regulations VALUES (218, 'small-business-job-protection-act', 'Small Business Job Protection Act', 'Tax', 'Pub. L. 104-188; 26 U.S.C. § 401 et seq.', NULL, 'Minimum distributions from tax-qualified retirement plans will not be required for workers over age 70.
INSERT INTO public.regulations VALUES (219, 'unrelated-business-income-ubit', 'Unrelated Business Income (UBIT)', 'Tax', '26 U.S.C. 511(a)(2)', NULL, 'Unrelated business income is income from a trade or business, regularly carried on, that is not substantially related to the charitable, educational, or other purpose that is the basis of the organization''s exemption.
INSERT INTO public.regulations VALUES (220, 'civil-service-reform-act-of-1978', 'Civil Service Reform Act of 1978', 'Unions', '5 U.S.C. § 7101 et seq.', NULL, 'These regulations establish a Bill of Rights for union members and set standards for union reports, trusteeships imposed on subordinate unions, elections of union officers, financial safe-guards, and other matters.
INSERT INTO public.regulations VALUES (221, 'national-labor-relations-act', 'National Labor Relations Act', 'Unions', '29 U.S.C. § 151 et seq.', NULL, 'It is an unfair labor practice for the University to: 1) Interfere with, restrain, or coerce employees in the exercise of their rights; 2) dominate or interfere with the formation or administration of any labor organization; 3) discriminate in any term or condition of employment; 4) encourage or discourage membership in any labor organization; or 5) refuse to bargain collectively with a labor organization''s representatives.', '', 'Human Resources', 'federal', true, NULL, NULL, '2026-06-25 15:35:16.352343', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The National Labor Relations Act (NLRA), codified at 29 U.S.C. §§ 151-169, establishes comprehensive federal labor law governing the rights of private sector employees, including those at private universities and colleges, to organize, bargain collectively, and engage in concerted activities. The Act, originally enacted in 1935 and administered by the National Labor Relations Board (NLRB) under 29 CFR Parts 100-200, explicitly prohibits universities from engaging in unfair labor practices that interfere with employees'' Section 7 rights under 29 U.S.C. § 157.
INSERT INTO public.regulations VALUES (222, 'consumer-credit-protection-act-title-iii-ccpa-garn', 'Consumer Credit Protection Act, Title III (CCPA) – Garnishments', 'Wages', '15 U.S.C. § 1673', NULL, 'Per Title III of the CCPA the maximum part of an employee''s total disposable earnings subject to garnishment in any workweek may not exceed the lesser of 25% of disposable earnings for that week or the amount by which disposable earnings for that week exceeds 30 times the federal minimum wage rate in effect at the time the earnings are payable. 1674 prohibits firing an employee because of garnishment and imposes a $1,000 fine for doing so.', '', 'Human Resources', 'federal', true, NULL, NULL, '2026-06-25 15:35:16.380887', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Consumer Credit Protection Act, Title III (CCPA), codified at 15 U.S.C. §§ 1671-1677, establishes federal limitations on wage garnishment and prohibits discriminatory employment practices related to garnishment orders. This federal law applies to all employers, including higher education institutions, that pay wages subject to garnishment orders issued by state or federal courts.
INSERT INTO public.regulations VALUES (223, 'fair-labor-standards-act-flsa', 'Fair Labor Standards Act (FLSA)', 'Wages', '29 U.S.C. §§ 201-219', NULL, 'Establishes minimum wage.
INSERT INTO public.regulations VALUES (236, 'new-jersey-tuition-aid-grant-program', 'New Jersey Tuition Aid Grant Program', 'General', 'N.J.A.C. 9A:9-2', NULL, 'Your institution must comply with New Jersey Tuition Aid Grant Program requirements to maintain eligibility for state financial aid distribution. You must verify student residency and eligibility, calculate awards accurately, maintain comprehensive records, and submit required reports to ensure continued program participation.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (224, 'qualified-tuition-reductions', 'Qualified Tuition Reductions', 'Wages', 'Publication', NULL, 'A qualified tuition reduction is any reduction in tuition provided to an employee for the education of an employee or certain relatives of the employee at the institution the employee works at or another qualified institution.
INSERT INTO public.regulations VALUES (225, 'pennsylvania-english-fluency-in-higher-education-a', 'Pennsylvania English Fluency In Higher Education A', 'Academic Programs', '24 P.S. § 6803 (Act 36 of 1990)', NULL, 'Pennsylvania statute requiring higher education institutions to ensure English language proficiency of all instructional faculty through assessment, testing, and student complaint procedures, with state funding penalties for non-compliance.', '', 'Academic Programs', 'state', true, NULL, NULL, '2026-06-25 15:35:16.46697', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Pennsylvania English Fluency in Higher Education Act, codified at 24 P.S. § 2510.1 et seq., establishes mandatory English language proficiency requirements for all instructional faculty at Pennsylvania''s higher education institutions. Enacted in 1990 and last amended in 2018, this regulation requires institutions to ensure that students can readily understand their instructors'' spoken English in classroom settings.
INSERT INTO public.regulations VALUES (226, 'pennsylvania-graduation-rates-reporting-act', 'Pennsylvania Graduation Rates Reporting Act', 'Academic Programs', '24 P.S. § 2510-301 (Act 88 of 1986)', NULL, 'This regulation implements Pennsylvania''s Graduation Rates Reporting Act, requiring all public educational institutions to submit comprehensive annual reports on graduation and retention rates. Reports must include demographic breakdowns, program-specific data, and employment outcomes. Institutions must use standardized cohort methodology and submit reports by March 15 annually. The Department of Education will compile statewide summaries and make data publicly available. Non-compliance may result in withheld state funding and required improvement plans.', '', 'Academic Programs', 'state', true, NULL, NULL, '2026-06-25 15:35:16.495067', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'PENNSYLVANIA GRADUATION RATES REPORTING REGULATION
INSERT INTO public.regulations VALUES (227, 'pennsylvania-higher-education-gift-disclosure-act', 'Pennsylvania Higher Education Gift Disclosure Act', 'Ethics', '22 Pa. Code § 31.41 (Act 188 of 1982)', NULL, 'Pennsylvania Act requiring higher education institutions to disclose gifts exceeding $50,000 individually or $100,000 aggregate annually, with enhanced reporting for foreign contributions above $25,000, enforced through state audits and funding penalties.', '', 'Ethics & Governance', 'state', true, NULL, NULL, '2026-06-25 15:35:16.523585', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Pennsylvania Higher Education Gift Disclosure Act, codified at 24 P.S. § 2510-A et seq., establishes comprehensive financial transparency requirements for institutions of higher education operating within Pennsylvania. Enacted to promote accountability and public awareness of significant financial contributions, this Act mandates disclosure of substantial gifts and donations received by covered educational institutions.
INSERT INTO public.regulations VALUES (228, 'pennsylvania-higher-education-standards', 'Pennsylvania Higher Education Standards', 'Academic Programs', '22 Pa. Code § 31.1 et seq.', NULL, '22 Pa. Code Ch. 31 establishes comprehensive academic and operational standards for Pennsylvania higher education institutions. The regulation covers academic program quality, institutional governance, faculty qualifications, student services, facilities, and distance learning requirements. Institutions must maintain appropriate accreditation, demonstrate financial stability, provide adequate student support services, and ensure faculty meet terminal degree requirements. Compliance is monitored through annual reporting, periodic reviews, and site visits by the Pennsylvania Department of Education. Non-compliance may result in probationary status, operational restrictions, or loss of authorization. The regulation promotes educational quality, student protection, and institutional accountability across all degree-granting institutions operating in Pennsylvania.', '', 'Academic Programs', 'state', true, NULL, NULL, '2026-06-25 15:35:16.551944', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'Pennsylvania Code Title 22, Chapter 31 establishes comprehensive academic standards and operational guidelines for higher education institutions operating within the Commonwealth of Pennsylvania. This regulation serves as the foundational framework ensuring educational quality, institutional accountability, and student protection across all postsecondary institutions.
INSERT INTO public.regulations VALUES (229, 'pennsylvania-institutional-accreditation', 'Pennsylvania Institutional Accreditation', 'General', '22 Pa. Code § 31.21', NULL, 'Your higher education institution must obtain authorization from the Pennsylvania Department of Education and maintain regional or national accreditation to operate and grant degrees in Pennsylvania. You must demonstrate financial stability, employ qualified faculty, maintain adequate facilities, and comply with ongoing reporting and oversight requirements.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (237, 'new-jersey-uniform-crime-reporting', 'New Jersey Uniform Crime Reporting', 'General', 'N.J.S.A. 52:17B-5', NULL, 'Your New Jersey higher education institution must participate in the state''s uniform crime reporting system by submitting detailed incident reports to the New Jersey State Police within specified timeframes. You must designate a qualified campus safety official to collect and compile crime data, establish formal procedures for gathering information from multiple sources, and maintain comprehensive public incident logs while ensuring victim confidentiality.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (230, 'pennsylvania-sexual-violence-education-act', 'Pennsylvania Sexual Violence Education Act', 'Sexual Misconduct', '24 P.S. § 20-2001 et seq. (Act 16 of 2014)', NULL, 'The Pennsylvania Sexual Violence Education Act requires all public school districts to implement age-appropriate sexual violence prevention education programs from grades K-12. Districts must use qualified instructors, trauma-informed approaches, and evidence-based curricula while maintaining parent notification requirements. Programs must address consent, healthy relationships, bystander intervention, and available resources. Schools must establish clear reporting protocols, collaborate with community partners, and maintain supportive environments that encourage disclosure of incidents.', 'PA SEXUAL VIOLENCE EDUCATION ACT (24 P.S. § 20-2001 et seq., Act 16 of 2014)
INSERT INTO public.regulations VALUES (231, 'pennsylvania-student-consumer-protection', 'Pennsylvania Student Consumer Protection', 'Student Services', '24 P.S. § 6601 et seq.', NULL, 'Pennsylvania Student Consumer Protection Standards under 22 Pa. Code Chapter 40 establish comprehensive transparency and accountability requirements for higher education institutions. The regulation mandates accurate disclosure of program information, costs, and outcomes while prohibiting deceptive marketing practices. Institutions must maintain clear complaint resolution procedures, designate compliance officers, and provide detailed financial information including refund policies. Special provisions address online education, career programs, and institutional closure procedures. Enforcement includes monitoring, investigations, and progressive sanctions. Annual reporting and documentation requirements ensure ongoing compliance. These standards protect student consumers while maintaining educational quality and institutional integrity throughout Pennsylvania''s higher education system.', '', 'Student Services', 'state', true, NULL, NULL, '2026-06-25 15:35:16.638608', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The Pennsylvania Student Consumer Protection Standards, codified under 22 Pa. Code Chapter 40, establish comprehensive consumer protection requirements for higher education institutions operating within the Commonwealth of Pennsylvania. These regulations are designed to ensure transparency, fairness, and accountability in institutional practices while protecting students from deceptive or unfair business practices in their educational pursuits.
INSERT INTO public.regulations VALUES (232, 'pennsylvania-uniform-crime-reporting-act', 'Pennsylvania Uniform Crime Reporting Act', 'General', '18 Pa.C.S. § 9101 et seq.', NULL, 'Your Pennsylvania higher education institution with sworn police officers must submit monthly Uniform Crime Reports to the Pennsylvania State Police within ten days of each month''s conclusion. You must report all Part I offenses, arrest data for Part II offenses, and detailed incident information through the National Incident-Based Reporting System format.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (233, 'new-jersey-campus-sex-assault-victim-bill-of-rights', 'New Jersey Campus Sex Assault Victim Bill Of Rights', 'General', 'N.J.S.A. 18A:61E-1 et seq.', NULL, 'Your New Jersey higher education institution must implement comprehensive policies and procedures to protect sexual assault victims and ensure fair, prompt investigation and resolution of complaints. You must provide essential support services including counseling, medical attention, and academic accommodations while maintaining strict confidentiality protections and preventing retaliation against victims.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (234, 'new-jersey-hazing-prevention', 'New Jersey Hazing Prevention', 'General', 'N.J.S.A. 2C:40-3 et seq.', NULL, 'Your educational institution must prevent hazing activities and establish comprehensive anti-hazing policies that apply to all student organizations, athletic teams, and groups. You must provide annual education programs, investigate reported incidents immediately, and cooperate with law enforcement when criminal activity is suspected.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (235, 'new-jersey-licensure-accreditation-standards', 'New Jersey Licensure Accreditation Standards', 'General', 'N.J.A.C. 9A:1-1 et seq.', NULL, 'Your post-secondary educational institution operating in New Jersey must obtain and maintain accreditation from recognized agencies while demonstrating operational stability, faculty qualifications, and financial viability. You must provide comprehensive student services, maintain rigorous academic standards, and submit to regular compliance monitoring by the Secretary of Higher Education.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (238, 'new-jersey-veterans-benefits-compliance', 'New Jersey Veterans Benefits Compliance', 'General', 'N.J.S.A. 18A:62-6', NULL, 'Your New Jersey higher education institution must provide comprehensive tuition benefits to qualified veterans and their dependents while maintaining proper eligibility verification and academic progress monitoring. You must designate certified veterans'' education officials, establish clear application procedures, and coordinate state benefits with federal programs to maximize student support.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (239, 'general-data-protection-regulation', 'General Data Protection Regulation (GDPR)', 'General', 'EU Regulation 2016/679', NULL, '', '', 'Information Technology', 'international', true, NULL, NULL, '2026-06-25 15:35:16.935783', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, 'The General Data Protection Regulation (EU Regulation 2016/679), commonly known as GDPR, represents one of the most comprehensive and stringent data protection frameworks in the world, with significant implications for higher education institutions that process personal data of individuals within the European Union. This regulation, which came into force on May 25, 2018, fundamentally transformed how educational institutions must approach data privacy, security, and individual rights, regardless of whether the institution is physically located within the EU.
INSERT INTO public.regulations VALUES (240, 'california-consumer-privacy-act', 'California Consumer Privacy Act', 'General', 'Cal. Civ. Code § 1798.100 et seq.', NULL, 'Your organization must comply with California''s consumer privacy requirements by providing transparency about data collection and allowing consumers to control their personal information. You must implement processes to handle consumer requests for data access, deletion, and opt-out of sales while maintaining detailed records of compliance activities.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (241, 'pennsylvania-act-55-of-2022-sexual-violence-higher-ed', 'PA Act 55 of 2022 - Sexual Violence in Higher Ed', 'Campus Safety', '24 P.S. § 20-2001-G et seq.', NULL, 'Your Pennsylvania higher education institution must establish comprehensive sexual violence prevention education programs for all students and maintain formal partnerships with local crisis centers. You must implement evidence-based programming addressing sexual violence, dating violence, domestic violence, and stalking, while ensuring students have access to confidential support services both on and off campus.', '## Key Compliance Requirements
INSERT INTO public.regulations VALUES (242, 'higher-education-act-recognition-of-accrediting', 'Higher Education Act: Recognition of Accrediting Agency or Association', 'Accreditation', 'Higher Education Act: Recognition of Accrediting Agency or Association', NULL, '', '', 'Academic Programs', 'federal', true, NULL, NULL, '2026-06-25 15:35:17.0246', NULL, NULL, NULL, NULL, '', '', '', NULL, '', NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2026-06-25 15:35:17.0246', NULL, true, NULL, NULL, NULL, NULL, '', NULL, NULL, 'federal', NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', false, 'annual', NULL, NULL, NULL, NULL, NULL, NULL, 'REG-012', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL);
