INSERT INTO public.compliance_tasks VALUES (5740, 138, NULL, '§ 1092(a), institutions must maintain qualified financial aid staff and make readily available throu...', '§ 1092(a), institutions must maintain qualified financial aid staff and make readily available through publications, mailings, and electronic media fifteen categories of information: (1) available financial aid programs; (2) distribution methods among recipients; (3) application requirements and procedures; (4) student rights and responsibilities; (5) cost of attendance calculations; (6) refund policies and Return to Title IV requirements; (7) academic program descriptions; (8) financial aid personnel contact information; (9) disability services and facilities; (10) accrediting agency names; (11) academic standards for aid eligibility; (12) completion and graduation rates; (13) loan deferment and cancellation provisions; (14) study abroad program aid applicability; and (15) annual campus security reports per the Clery Act', '', NULL, 'Financial Aid Director', NULL, NULL, 30, 'pending', 'high', NULL, NULL, true, 'document', '', 0, false, '2026-06-25 15:36:32.109254', '2026-06-25 15:36:32.109254', NULL, NULL, NULL, NULL, 'task-1772645761497-z35mnf', 'requirement', 'Compliance Requirement', '', '20 U.S.C. § 1092(a)', NULL, NULL, NULL, NULL, 'not_required', '', '', '', NULL, NULL, NULL, false, NULL, NULL);
