INSERT INTO public.compliance_tasks VALUES (5277, 123, NULL, 'Establish borrower contact and default aversion procedures', 'Implement systematic contact procedures for borrowers approaching or entering default status', '', NULL, 'Financial Aid Director', NULL, NULL, 30, 'pending', 'high', NULL, NULL, true, 'document', '', 13, false, '2026-06-25 15:36:13.764291', '2026-06-25 15:36:13.764291', NULL, NULL, NULL, NULL, 'ai-task-1772645088131-p1t344', 'requirement', 'Student Services', '', '20 U.S.C. § 1015a; 20 U.S.C. § 1085', NULL, NULL, NULL, NULL, 'not_required', '', '', '', NULL, NULL, NULL, false, NULL, NULL);
INSERT INTO public.compliance_tasks VALUES (5317, 124, NULL, 'Ensure financial aid staff complete required training', 'Provide comprehensive training on regulatory compliance, financial management, and student eligibility', '', NULL, 'Financial Aid Director', NULL, NULL, 30, 'pending', 'high', NULL, NULL, true, 'document', '', 24, false, '2026-06-25 15:36:15.300283', '2026-06-25 15:36:15.300283', NULL, NULL, NULL, NULL, 'ai-task-1772645129576-90xerq', 'requirement', 'Training', '', '34 CFR § 668.16(a)', NULL, NULL, NULL, NULL, 'not_required', '', '', '', NULL, NULL, NULL, false, NULL, NULL);
