INSERT INTO public.compliance_tasks VALUES (5648, 136, NULL, 'Institutions must establish written policies addressing conflicts of interest, particularly regardin...', 'Institutions must establish written policies addressing conflicts of interest, particularly regarding preferred lender arrangements under 20 U', '', NULL, 'Financial Aid Director', NULL, NULL, 30, 'pending', 'high', NULL, NULL, true, 'document', '', 0, false, '2026-06-25 15:36:28.349807', '2026-06-25 15:36:28.349807', NULL, NULL, NULL, NULL, 'task-1772645528145-em1nyu', 'requirement', 'Compliance Requirement', '', '20 U.S.C. § 1094(a)(25)', NULL, NULL, NULL, NULL, 'not_required', '', '', '', NULL, NULL, NULL, false, NULL, NULL);
